(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c56"]=[{"id":"00009306","register_sub_id":"101","register_pk":"194099","name":"森家住宅土蔵","kana":"もりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市羽津町4110","lat":34.98859094,"lng":136.63644373,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"24 － 0122","desc":"敷地北東隅に建つ。桁行六メートル梁間四・一メートル、切妻造桟瓦葺で南面中央に出入口を設ける。南面二階と西面一階に窓を穿ち、桟瓦葺の庇を付ける。小屋は和小屋とする。道具類を収蔵するための蔵で、明治期における町家の面影を今に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009306"},{"id":"00012936","register_sub_id":"101","register_pk":"368017","name":"山中家住宅北蔵","kana":"やまなかけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町200","lat":34.61888333,"lng":136.08735833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 271","desc":"主屋北棟の西側に東面して建つ調度蔵。土蔵造二階建、切妻造桟瓦葺妻入で、正面に吹放し下屋を付す。外壁は漆喰塗で鉢巻三段を廻し、腰を海鼠壁とする。内部は上下階とも板敷で、壁は横板張、小屋は登梁。離れとともに敷地西北隅の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012936"},{"id":"00012934","register_sub_id":"101","register_pk":"368015","name":"山中家住宅主屋","kana":"やまなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町200","lat":34.61878333,"lng":136.08747778,"geo_status":"db","era":"江戸末期／昭和59年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積209㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 269","desc":"市中心部、初瀬街道沿いのもと宿屋。主屋は街道に東面して建つ。切妻造の北棟と入母屋造の南棟からなるつし二階建で、正面下屋上を白漆喰で軒裏まで塗込める。両棟とも3室を並べて奧を座敷とし、北棟は南に土間を通す。近世宿場町の景観を伝える町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012934"},{"id":"00012935","register_sub_id":"101","register_pk":"368016","name":"山中家住宅離れ","kana":"やまなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市本町200","lat":34.61891111,"lng":136.08726667,"geo_status":"db","era":"明治前期／明治中期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 270","desc":"敷地西北隅に南面して建つ。切妻造桟瓦葺の二階建で、上下階とも８畳の座敷と六畳の次の間を並べ、南面に縁を設けて中庭を臨む。一階は根太天井で装飾少なく簡素につくるが、二階は付書院や彫刻欄間に趣向を凝らす。瀟洒な意匠をもつ良質な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012935"},{"id":"00012937","register_sub_id":"101","register_pk":"368018","name":"山中家住宅南蔵","kana":"やまなかけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町200","lat":34.61874167,"lng":136.08722222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 272","desc":"敷地西南隅に北面して建つ穀物蔵。切妻造桟瓦葺、土蔵造二階建の正面に吹放し下屋を付す。外壁は中塗仕上で、鉢巻二段を廻す。内部は上下階とも板敷、壁縦板張で、中央の梁上に束を立てた和小屋とする。主屋の座敷や離れから臨む中庭景観の添景となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012937"},{"id":"00013261","register_sub_id":"101","register_pk":"366250","name":"横山家住宅主屋","kana":"よこやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2657","lat":35.01000833,"lng":136.50689722,"geo_status":"db","era":"江戸末期／大正8年改修、昭和前期・同40年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部金属板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0276","desc":"鈴鹿山系御在所岳を望む扇状地に位置し、屋根は入母屋造で起り付の桟瓦葺とし、屋根の南面西寄りに千鳥破風を設ける。四周に下屋を廻らせ、玄関に切妻の庇をつける。東が土間、西が床上で、仏間に床と仏壇を設ける。重厚な外観の上層農家の住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013261"},{"id":"00013264","register_sub_id":"101","register_pk":"366253","name":"横山家住宅旧診療所","kana":"よこやまけじゅうたくきゅうしんりょうじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2657","lat":35.01,"lng":136.50713889,"geo_status":"db","era":"明治後期／昭和20年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0279","desc":"主屋の東に建つ寄棟造の南北棟で、桟瓦葺とする。外壁は腰高を木製シングルの鱗張り、上部を竪板張とする。軒先は円弧断面に漆喰を塗込める。西面に瓦葺下屋の廊下がつく。内部は南から旧待合室、旧診察室、旧レントゲン室が並ぶ。特色ある外観が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013264"},{"id":"00013262","register_sub_id":"101","register_pk":"366251","name":"横山家住宅書院及び渡廊下","kana":"よこやまけじゅうたくしょいんおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和後","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2657他","lat":35.01003056,"lng":136.506725,"geo_status":"db","era":"昭和43年頃","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、瓦葺一部金属板葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0277","desc":"書院は主屋の西に渡廊下で接続し、西の座敷10畳と次の間6畳からなる。座敷は琵琶棚、付書院を持ち、床脇は天袋付の違棚とする。北、東、南に縁を廻らす。西面に腰掛待合を付す。南に重森三玲作庭の枯山水庭園を望む。清明な造作の現代の和風書院である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013262"},{"id":"00013263","register_sub_id":"101","register_pk":"366252","name":"横山家住宅尽日庵","kana":"よこやまけじゅうたくじんじつあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2656","lat":35.00995556,"lng":136.50660833,"geo_status":"db","era":"明治中期／昭和27年頃・同43年頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺一部金属板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0278","desc":"書院の南西に建つ切妻造、桟瓦葺の草庵風茶室である。北庇に躙口、東庇に濡縁を設けて貴人口を開き、書院西妻の腰掛待合から飛石で導く。内部は二畳台目で、西面の洞床の前に板床を入れる。南から西へ縁を廻らし、西に水屋を突出する。近代数寄屋の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013263"},{"id":"00013266","register_sub_id":"101","register_pk":"366255","name":"横山家住宅正門","kana":"よこやまけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2657","lat":35.00985,"lng":136.50701111,"geo_status":"db","era":"江戸後期／昭和40年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口4.2m","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0281","desc":"主屋の南東に南面して建つ薬医門。切妻造の起り付屋根を桟瓦葺とする。門柱は五平使いで、板戸を引分けに建込み、東脇間に潜戸を設ける。冠木を両妻面まで延ばし、両妻で控柱上の桁に梁を掛渡して軒桁を据える。土間石敷の水切溝は重森の作庭時のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013266"},{"id":"00013265","register_sub_id":"101","register_pk":"366254","name":"横山家住宅土蔵","kana":"よこやまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県三重郡菰野町大字菰野字中里2657","lat":35.01009444,"lng":136.50702778,"geo_status":"db","era":"江戸末期／大正8年頃・平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0280","desc":"主屋の北東、北側道路沿いに建つ。切妻造の置屋根を桟瓦葺とし、南面に瓦葺庇がつく。外壁は一階が簓子下見板張り、二階が漆喰塗で鉢巻を廻し、東西妻に竪羽目板を張る。南面戸口は銅板張りの片引戸である。小屋組は登梁とする。敷地北側の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013265"},{"id":"00015469","register_sub_id":"101","register_pk":"533484","name":"赤田家住宅主屋","kana":"あかだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市太田町133","lat":35.46795556,"lng":136.31501389,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0525","desc":"琵琶湖北東の農村集落に位置する旧家の主屋。敷地北西に南面して建つ、二階建片入母屋造桟瓦葺で西に入母屋造の平屋を突出する。内部は東を土間とした六間取、二階は一室でかつての蚕室。南西隅を座敷とし軸部など漆塗とする。庭への眺望が優れた上質な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015469"},{"id":"00015473","register_sub_id":"101","register_pk":"533488","name":"赤田家住宅正門","kana":"あかだけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市太田町字中屋敷133-1","lat":35.46777778,"lng":136.31513611,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、茅葺、間口2.3m、袖塀付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0529","desc":"主屋正面に位置し、南面して建つ薬医門。切妻造茅葺で両脇に桟瓦葺の袖塀を付し、東に潜戸を設ける。主柱間の冠木上に架けた梁の鼻先で軒桁を支持し、丸太の垂木を架ける。内部は天井を張り、門口に両開板扉を吊る。茅葺屋根が地域の歴史的景観をつくる正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015473"},{"id":"00015471","register_sub_id":"101","register_pk":"533486","name":"赤田家住宅土蔵","kana":"あかだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市太田町133","lat":35.46801667,"lng":136.314925,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0527","desc":"主屋の北西に位置する家財蔵。花崗岩基礎に建つ土蔵造二階建切妻造妻入で東面の戸口に下屋を付し、屋根は置屋根形式の桟瓦葺。外壁は漆喰塗仕上で腰はモルタル洗出仕上とする。内部は各階板敷で、小屋には曲がり材の梁を用いる。屋敷北西の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015471"},{"id":"00015470","register_sub_id":"101","register_pk":"533485","name":"赤田家住宅離れ座敷","kana":"あかだけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市太田町133","lat":35.4679,"lng":136.31524722,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0526","desc":"主屋の南東に位置し西面して建つ離れ座敷。二階建切妻造平入桟瓦葺で、周囲に下屋を廻らす。内部は北西の踏込土間から東の続き間座敷へ至り、南西に三畳の書斎を配し、西面に円窓を開ける。皮付アカマツの床柱やクロガキの框など材料を吟味した上質な座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015470"},{"id":"00015472","register_sub_id":"101","register_pk":"533487","name":"赤田家住宅物置","kana":"あかだけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"滋賀県","address":"滋賀県長浜市太田町133","lat":35.46780278,"lng":136.31518889,"geo_status":"db","era":"昭和42年頃","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0528","desc":"主屋の南西に位置する物置。平屋建切妻造の東西棟で屋根桟瓦葺とし、外壁は上部を荒壁仕上で鉄板を張り、腰は下見板張とする。内部は東西二室の土間で上部に小屋組を現し、西妻と北面東寄りに戸口を開け板戸を建てる。正門と並び屋敷の表構えをつくる物置。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015472"},{"id":"00009037","register_sub_id":"101","register_pk":"162397","name":"秋口家住宅洋館","kana":"あきぐちけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県彦根市芹町726","lat":35.2602652,"lng":136.25962315,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0305","desc":"敷地中ほどに北面して建ち、桁行１１．２ｍ梁間５．９ｍ、木造二階建、寄棟造桟瓦葺である。外壁は下見板張で、各室に上げ下げ窓を開ける。当初は歯科医院として建てられたため、洋風意匠を基調とした二階の旧診察室などに、その名残をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009037"},{"id":"00012170","register_sub_id":"101","register_pk":"352970","name":"猪飼家住宅長屋門・看板所","kana":"いかいけじゅうたくながやもん・かんばんじょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県栗東市手原四丁目1114","lat":35.025836,"lng":135.997731,"geo_status":"db","era":"江戸末期／昭和期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"長屋門 木造平屋建、瓦葺、建築面積76㎡ 看板所 木造、瓦葺、間口0.8m","structure_material":"長屋門 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-408","desc":"東海道に北面する入母屋造の長屋門。中央の門口に重厚な扉を開く。西側の室の東面を式台として虹梁を架ける特異な形式をもち、東側は床付の十畳とする。外観は漆喰塗と簓子下見板張で与力窓を設ける。代官所の風格を備えつつ、看板所が薬種業の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012170"},{"id":"00012171","register_sub_id":"101","register_pk":"352971","name":"猪飼家住宅長屋門塀","kana":"いかいけじゅうたくながやもんへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県栗東市手原四丁目1114","lat":35.025859,"lng":135.99787,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長9.1m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"25-409","desc":"長屋門の北東隅から東にのびて敷地を画す塀。延長九・一メートル、切妻造桟瓦葺で、東寄りの潜りに板戸を片開きとする。切石積基礎に布石を伏せて柱を立て、腕木で軒を受ける。壁は外部漆喰塗で腰を竪板張とする。長屋門とともに街道筋の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012171"},{"id":"00008131","register_sub_id":"101","register_pk":"132529","name":"石田家住宅主屋","kana":"いしだけいしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央1-409他","lat":35.00945159,"lng":135.86455692,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0282","desc":"敷地中央に建つ木造平屋建。東西棟の切妻造桟瓦葺で、北面東寄りに洋館への廊下や玄関を付ける。西に八畳と六畳の続き座敷、東に台所等を配する。八畳に座敷飾りを構え、六畳に仏壇を置く。玄関には浅い庇を掛け、細丸太の化粧垂木など数寄屋風の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008131"},{"id":"00012166","register_sub_id":"101","register_pk":"352966","name":"粋世主屋","kana":"いなせしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等三丁目301","lat":35.011189,"lng":135.859962,"geo_status":"db","era":"昭和8年／平成28年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡、塀付","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"25-404","desc":"大津市街地の浜通り南側に位置する木造二階建、切妻造の町家。平面は正面左に広く土間を取り、その奥を通り土間とする。向かって右には街路側から一室を挟んで中庭を取り、その南には次の間、座敷を配し、二階には洋室を設ける。地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012166"},{"id":"00013274","register_sub_id":"101","register_pk":null,"name":"岩崎家住宅主屋","kana":"いわさきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市木戸字西替戸1008","lat":35.19963889,"lng":135.92026667,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0454","desc":"大津市北郊の集落に所在する。琵琶湖を望み東面し、寄棟造茅葺で下屋を廻らす。北寄りを土間とし、床上部は整型四間取の上手に座敷を増築するなど順次拡張している。四室の前二室の軸部加工は特に古風で、江戸中期の古材を包含した湖西の民家として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013274"},{"id":"00013825","register_sub_id":"101","register_pk":"507787","name":"岩根家住宅（重内）主屋","kana":"いわねけじゅうたく（じゅうない）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字傳馬町930他","lat":35.50444722,"lng":136.22609722,"geo_status":"db","era":"江戸末期／大正後期増築改修、平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"25 － 0478","desc":"旧北国街道木之本宿の中程に西面する。入母屋造桟瓦葺で四周に下屋を廻し、南面東端に角屋を設ける。外壁は鼠漆喰仕上で二階に格子窓、一階に出格子を設ける。内部は北に玄関と土間、南に二列七室を並べ奥に座敷を配する。町並では希少な妻入町家として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013825"},{"id":"00009322","register_sub_id":"101","register_pk":"194115","name":"上野家住宅主屋","kana":"うえのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市本町2-61","lat":35.27276336,"lng":136.25009154,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積97㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0320","desc":"彦根城下西側で、枡形の角地に南面して建つ。木造平屋一部二階建、建築面積九七平方メートル、切妻造桟瓦葺。上階正面は中央二間を格子窓とし、両脇間を鼠漆喰塗として東間に虫籠窓を穿ち、両端に袖卯建を設ける。旧道の突当りにあって特徴的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009322"},{"id":"00007753","register_sub_id":"101","register_pk":"108734","name":"ウォーターハウス記念館本館（旧ウォーターハウスレジデンス主屋）","kana":"うぉーたーはうすきねんかんほんかん（きゅううぉーたーはうすれじでんすしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市池田町5-21","lat":35.13496565,"lng":136.08798798,"geo_status":"db","era":"大正2／平成20改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造3階建、スレート葺、建築面積114㎡","structure_material":"木造3階建","registered":"2009.08.07(平成21.08.07)","register_no":"25-0278","desc":"通りに東面して建つ。木造３階建、東西棟の切妻造スレート葺のシンプルな外観になる。東面北寄りに差掛け屋根のポーチを突出させ、北側に階段や水まわり、南側に居間や食堂を配し、２、３階を寝室や書斎、客間等に充てる。ヴォーリズの初期の設計になる住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007753"},{"id":"00007754","register_sub_id":"101","register_pk":"108735","name":"ウォーターハウス記念館門及び塀（旧ウォーターハウスレジデンス門及び塀）","kana":"うぉーたーはうすきねんかんもんおよびへい（きゅううぉーたーはうすれじでんすもんおよびへい）","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市池田町5-21","lat":35.13502831,"lng":136.08818667,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"門 煉瓦造、間口4.0m、塀 煉瓦造、総延長12m","structure_material":"門 煉瓦造","registered":"2009.08.07(平成21.08.07)","register_no":"25-0279","desc":"通りに東面する敷地正面に建つ。０．４８ｍ角、高さ１．９ｍの煉瓦積の柱を間口４．０ｍに建てる。塀は南に４．２ｍ、北に７．９ｍ。門柱と同じ大きさの煉瓦柱を建て、柱間に煉瓦を２段に積む。焼成時変形煉瓦を使い、太めの目地で、風趣ある構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007754"},{"id":"00002269","register_sub_id":"101","register_pk":"103259","name":"延暦寺大書院","kana":"えんりゃくじだいしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町4220","lat":35.070042,"lng":135.842941,"geo_status":"db","era":"大正8頃／昭和3移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦一部銅板葺、建築面積839㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0145","desc":"根本中堂の東方にある。もと東京赤坂にあった村井氏の山王荘の一部で，設計は武田五一，棟梁は小林富蔵。唐破風の車寄を持つ玄関棟，旭光の間と呼ぶ大客室棟，観月台を持つ２階建の居間棟からなる。洗練された書院造で，技術的にも優れた質の高い和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002269"},{"id":"00002270","register_sub_id":"101","register_pk":"103260","name":"延暦寺大書院庭門","kana":"えんりゃくじだいしょいんにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町4220","lat":35.070255,"lng":135.842896,"geo_status":"db","era":"大正8頃／昭和3移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、銅板葺、間口2.3m","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0146","desc":"移築前と同じ位置，大客室棟の背面に延びた塀の中間に設けられ，玄関側前庭と旭光の間から望む庭側を結ぶ。１間１戸の平唐門で，軒は疎垂木・木舞打，屋根は銅板葺。花挟間風の欄間，棟木を受ける蟇股など，繊細で流麗な造形で，規模は小さいが見所に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002270"},{"id":"00000441","register_sub_id":"101","register_pk":"101431","name":"近江日野商人館（旧山中兵右衛門家住宅）井戸屋形","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）いどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01151492,"lng":136.24755069,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積11㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0022","desc":"主屋主体部の西に取り付く釜屋の西方に平行して軒を接して建つ，切妻造，桟瓦葺の小規模な建物。北方を吹き放ちとし，南方に部屋を設けてボイラー（昭和18年製）を置く。商人のくらしの近代を知ることができる私設として意義がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000441"},{"id":"00000438","register_sub_id":"101","register_pk":"101428","name":"近江日野商人館（旧山中兵右衛門家住宅）表門","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01142882,"lng":136.24766294,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造棟門，瓦葺，石橋附属，左右屋根塀延長47m附属","structure_material":"木造棟門","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0019","desc":"主屋主体部の正面西寄りにある式台の南方にあり，道路からわずかに奥に引き込んで建つ。正面に小規模な石橋，左右に板塀が附属する棟門で，主体部の１階屋根より高さを低く押さえて，視覚的な効果を出す。商人の邸宅の屋敷構えを構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000438"},{"id":"00000437","register_sub_id":"101","register_pk":"101427","name":"近江日野商人館（旧山中兵右衛門家住宅）主屋","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01152102,"lng":136.24770198,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建，瓦葺，建築面積280㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0018","desc":"酒の醸造，鉛の販売等で栄えた山中家の邸宅を資料館にしたもの。入母屋造，２階建の主体部の両脇に平屋建の座敷と釜屋がついた構成になる。中廊下で和室と洋室を区切る主体部１階の平面形式に，昭和初期の和風邸宅の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000437"},{"id":"00000440","register_sub_id":"101","register_pk":"101430","name":"近江日野商人館（旧山中兵右衛門家住宅）西蔵","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01165401,"lng":136.24748969,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積58㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0021","desc":"東蔵の西に建つ２階建，平入の土蔵。腰に水切りを付けその下を縦板で覆い，軒に鉢巻をまわすなど，東蔵と比較して本格的なつくりになる。もとは，東西蔵の他にも蔵があったという。日野商人の往時の繁栄の様子を伝える建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000440"},{"id":"00000439","register_sub_id":"101","register_pk":"101429","name":"近江日野商人館（旧山中兵右衛門家住宅）東蔵","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01167231,"lng":136.24762024,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積32㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0020","desc":"主屋主体部の西に取り付く釜屋の北方に東西に棟を向けて建つ２階建，平入の土蔵。比較的に小規模で簡略な形式になるが，邸宅の屋敷構えを構成する一要素となっており，日野商人の生活の様子を伝える建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000439"},{"id":"00000442","register_sub_id":"101","register_pk":"101432","name":"近江日野商人館（旧山中兵右衛門家住宅）物置","kana":"おうみひのしょうにんかん（きゅうやまなかひょうえもんけじゅうたく）ものおき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1011","lat":35.01156983,"lng":136.24754703,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積5㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0023","desc":"井戸屋形の北に接続し，主屋の釜屋と軒を接して建つ。切妻造，桟瓦葺の小規模で簡素な建物で，外壁を縦板張りとする。部材等から井戸屋形と同時期の考えられ，往時の生活の様子を示す施設として意義がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000442"},{"id":"00000872","register_sub_id":"101","register_pk":"101862","name":"大村家住宅主屋","kana":"おおむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県高島市マキノ町白谷343","lat":35.49954408,"lng":136.04132157,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建，茅葺，建築面積156㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0094","desc":"「大浦型」と呼ばれる形式をもつ民家。平面形式は「六っ住い」とも呼ばれ，奥の３室（おえ，でえ，ざしき）と玄関側の３室（だいどころ，いたのま，げんかん）で構成される。昭和50年からは民俗資料館として公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000872"},{"id":"00000873","register_sub_id":"101","register_pk":"101863","name":"大村家住宅土蔵","kana":"おおむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県高島市マキノ町白谷343","lat":35.49937954,"lng":136.04129696,"geo_status":"db","era":"嘉永7","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積32㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0095","desc":"２階建の土蔵。妻側にある入口上部の冠木に，竜と波頭の漆喰鏝細工がなされている。付近では土蔵の白壁が禁止されていたために，白壁のこの土蔵は琵琶湖の船舶の目印となり，「灯台の蔵」と呼ばれて広く知られていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000873"},{"id":"00012179","register_sub_id":"101","register_pk":"352979","name":"岡家住宅主屋","kana":"おかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県蒲生郡日野町鎌掛2301","lat":34.986895,"lng":136.261475,"geo_status":"db","era":"昭和14年／昭和41年増築","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"25-417","desc":"ヴォーリズ建築事務所による和洋折衷住宅。外観は赤瓦葺、色モルタル塗で、玄関は和風意匠。中廊下式の平面で、サンルームや台所、洋風寝室などに近代的要素を示し、座敷飾りやサンルームの飾棚などに和風意匠を取り入れる。収納や造付家具にも特徴をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012179"},{"id":"00008711","register_sub_id":"101","register_pk":"149432","name":"小川家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市京町3-219","lat":35.00618827,"lng":135.86708869,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"25 － 0294","desc":"旧東海道に北面して建つ平入町家。間口四4.9ｍの木造2階建、切妻造桟瓦葺。東側に通りニワを設け、西に1列4室を配する。2階も4室に間仕切り、大津祭の巡行がある通り側には大きく窓を開ける。近世の小規模町家を近代に改修した歴史をよく伝える住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008711"},{"id":"00008712","register_sub_id":"101","register_pk":"149433","name":"小川家住宅土蔵","kana":"おがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市京町3-219","lat":35.00606119,"lng":135.86703092,"geo_status":"db","era":"江戸末期／昭和後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積10㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"25 － 0295","desc":"短冊形の敷地南奥、主屋と中庭を挟んだ位置に建つ。切妻造妻入桟瓦葺。桁行3.7ｍ梁間2.8ｍの2階建土蔵。北面に瓦葺庇をかけ、掛子塗の開戸を吊る。切石積基礎とし、外壁は漆喰で軒裏まで塗り込める。小庇の持送りなど丁寧な仕上げが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008712"},{"id":"00003107","register_sub_id":"101","register_pk":"104097","name":"奥伊吹ふるさと伝承館","kana":"おくいぶきふるさとでんしょうかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県米原市甲津原","lat":35.51048407,"lng":136.36143559,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0203","desc":"伊吹山北方の姉川上流部にある入母屋造，茅葺の妻入民家。天保７年（１８３６）の大火に焼け残ったとされ，ダイドコではこの地方に今も残る能が演じられたと伝える。旧所有者の竹中家から町が寄付を受け移築修理をして現在民俗資料館に活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003107"},{"id":"00009321","register_sub_id":"101","register_pk":"194114","name":"奥野家住宅主屋","kana":"おくのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市本町2-102","lat":35.27125121,"lng":136.25124796,"geo_status":"db","era":"安政2年","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積314㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0319","desc":"彦根城の南西側に建ち、木造平屋一部二階建、桁行二〇・二メートル梁間一七・七メートル、切妻造桟瓦葺である。下階正面は腰に簓子下見板を張り、上階は大壁で虫籠窓や出格子を設ける。床上部は三列構成で、座敷の造作も優れている。城下町に残る大型の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009321"},{"id":"00011974","register_sub_id":"101","register_pk":"354925","name":"奥村家住宅主屋","kana":"おくむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等二丁目408-1","lat":35.008962,"lng":135.858366,"geo_status":"db","era":"昭和10年／平成27年曳家","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡、門付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"25-398","desc":"大津市街地の西方、北国街道に西面する木造二階建、桟瓦葺の町家。向かって左に土間を通し、大島産御影石の腰壁上に格子を設ける右側に居室一列を並べる。二階は正面側に広間を、奥に座敷を取り、台所上部は吹抜けとする。街道沿いの景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011974"},{"id":"00008715","register_sub_id":"101","register_pk":"149436","name":"おっきん椋川交流館（旧栗田家住宅主屋）","kana":"おっきんむくがわこうりゅうかん（きゅうくりたけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県高島市今津町椋川字尾條286","lat":35.40230752,"lng":135.91156139,"geo_status":"db","era":"明治14年／平成21年改修","year":1881,"year_source":"converted","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、茅葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"25 － 0298","desc":"山間の集落内、山を背に南面して建つ。桁行16ｍ梁間10ｍ、入母屋造茅葺の農家。中央に入口土間を設け、その奥を12畳規模のダイドコとし、囲炉裏を設ける。東面に3室並べ、北奥にトコとトコ脇、平書院を備える座敷とする。山村の佇まいを残す茅葺民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008715"},{"id":"00001522","register_sub_id":"101","register_pk":"102512","name":"柏原宿歴史館収蔵庫","kana":"かしわばらじゅくれきしかんしゅうぞうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県米原市柏原2101","lat":35.34239355,"lng":136.39852352,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"25 － 0124","desc":"主屋の西北方で，展示館の南側に矩折りに建つ南北棟の土蔵。２階建，切妻造，桟瓦葺，平入の標準的造りになる土蔵で，展示館の土蔵の約半分の規模。展示館と同様に改修されて，関係資料を収蔵する収蔵庫棟として利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001522"},{"id":"00001520","register_sub_id":"101","register_pk":"102510","name":"柏原宿歴史館主屋","kana":"かしわばらじゅくれきしかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市柏原2101","lat":35.342304,"lng":136.39876204,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"25 － 0122","desc":"中山道関ヶ原宿と醒井宿の間の宿にあたる柏原宿の中程に位置し中山道に南面して建つ。染料関係で財をなした松浦氏の邸宅で，中山道に向けて三つの入母屋造妻飾りを重ねる重厚な表構えに特徴がある。地棟墨書から上棟年と「大工頭梁西村豊太郎」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001520"},{"id":"00001521","register_sub_id":"101","register_pk":"102511","name":"柏原宿歴史館展示館","kana":"かしわばらしゅくれきしかんてんじかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県米原市柏原2101","lat":35.34246086,"lng":136.39855048,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"25 － 0123","desc":"敷地の北端，西寄りに建つ２階建，切妻造，東西棟，桟瓦葺，平入の土蔵で，旧松浦邸の屋敷構えを構成する主要な付属建物になる。歴史館への再生にあたり改修されて，１階２階とも柏原宿の関係資料を展示する展示館として活用が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001521"},{"id":"00001523","register_sub_id":"101","register_pk":"102513","name":"柏原宿歴史館門","kana":"かしわばらじゅくれきしかんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市柏原2101","lat":35.3421551,"lng":136.39873348,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造棟門、瓦葺、間口2m、左右屋根塀延長9.6m附属","structure_material":"木造棟門","registered":"2000.02.15(平成12.02.15)","register_no":"25 － 0125","desc":"主屋前面西寄りの角屋の南西端から発する桟瓦葺の屋根付板塀で，ほぼ中央に棟を高くした一間幅の門を開く。屋敷の表構えを形成する上で欠くことのできない要素であるとともに，中山道宿場町の景観を整えている歴史的景観構成要素としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001523"},{"id":"00000985","register_sub_id":"101","register_pk":"101975","name":"ガリ版伝承館（旧堀井家住宅洋館）","kana":"がりばんでんしょうかん（きゅうほりいけじゅうたくようかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市蒲生岡本町663","lat":35.03963824,"lng":136.19537879,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造２階建，瓦葺，建築面積49㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0108","desc":"謄写版発明で著名な堀井新治郎・耕造親子が郷里に建設したもの。棟梁は大阪の野口清蔵。木造２階建，寄棟瓦葺，下見板張，一室構成の洋館で，主屋の東方に位置し，当初は離れ座敷に接続していたが，現在は東に玄関部を新設して記念館として保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000985"},{"id":"00013270","register_sub_id":"101","register_pk":"366259","name":"川上家住宅","kana":"かわかみけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央一丁目115-3","lat":35.00778333,"lng":135.86363889,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0450","desc":"通りから小路を入った突当りに南面して建つ。二戸一棟の木造二階建長屋の西半部。間口二間強、奥行五間で、正面東寄りの玄関にガラス戸を建て、西側に出格子を作り、二階座敷に床や透彫欄間を設える。敷地後方に位置しつつ、大津の長屋の立面特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013270"},{"id":"00000542","register_sub_id":"101","register_pk":"101532","name":"川﨑光雄家住宅北蔵","kana":"かわさきみつおけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県栗東市手原5-4-28","lat":35.02591896,"lng":135.99669756,"geo_status":"db","era":"大正1頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積17㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0034","desc":"北西の敷地境界に接して建ち，離れに連なる。主屋に棟を平行にした平入り２階建ての土蔵で，東蔵の倍の規模を有する。もと米蔵。腰を立ちの高い縦板貼りとし，東蔵と同様に置屋根形式を採るが，緩やかなムクリをつける。屋敷構えの主要な構成要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000542"},{"id":"00000541","register_sub_id":"101","register_pk":"101531","name":"川﨑光雄家住宅主屋","kana":"かわさきみつおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原5-4-28","lat":35.02586235,"lng":135.99683992,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積209㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0033","desc":"旧東海道に面するが，街道からは退いて建つ。つし２階の造りで，東を落棟とする。つし２階は塗り込められ，緩やかなムクリをもつ主屋根に煙出しを付す。近世以来の当地方の農家の形式を踏襲してはいるが，大正期的な洗練度を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000541"},{"id":"00000543","register_sub_id":"101","register_pk":"101533","name":"川﨑光雄家住宅南蔵","kana":"かわさきみつおけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県栗東市手原5-4-28","lat":35.02586901,"lng":135.99669423,"geo_status":"db","era":"大正1頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積30㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0035","desc":"北蔵に連なって建つ。北蔵と同様の造りで，西面１階に庇付き窓，２階に２個所の窓をとる。北蔵より規模は大きいが，棟をやや低く押さえ蔵の地位を示している。屋敷構えの主要な構成要素であり，街路景観上でも重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000543"},{"id":"00000540","register_sub_id":"101","register_pk":"101530","name":"川﨑睦男家住宅北蔵","kana":"かわさきむつおけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県栗東市手原5-3-10","lat":35.02618419,"lng":135.99657748,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造２階建，瓦葺，建築面積40㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0032","desc":"北西の敷地境界に接して建ち，離れに連なる。主屋に棟を平行にした平入り２階建ての土蔵で，東蔵の倍の規模を有する。もと米蔵。腰を立ちの高い縦板貼りとし，東蔵と同様に置屋根形式を採るが，緩やかなムクリをつける。屋敷構えの主要な構成要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000540"},{"id":"00000537","register_sub_id":"101","register_pk":"101527","name":"川﨑睦男家住宅主屋","kana":"かわさきむつおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原5-3-10","lat":35.02606182,"lng":135.99670783,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積151㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0029","desc":"東海道旧道に面する。つし２階の主屋を中央にして，右手に東蔵，左手に平屋の棟，奥に北蔵と離れ座敷を配する。１階の紅殻の格子窓，塗り込めたつし２階，煙出しの棟などに，当地方にみられる近世来の町屋の特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000537"},{"id":"00000538","register_sub_id":"101","register_pk":"101528","name":"川﨑睦男家住宅離れ","kana":"かわさきむつおけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県栗東市手原5-3-10","lat":35.02616823,"lng":135.99671794,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，瓦葺，建築面積35㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0030","desc":"主屋の北側，敷地境界に接し，北蔵に連なって建つ。２階建に入母屋瓦葺きの平屋を東方に突き出す。つし２階の主屋に対して，２階建と平屋の書院より成る離れの建築構成に当地方における住宅建築の変化をみることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000538"},{"id":"00000539","register_sub_id":"101","register_pk":"101529","name":"川﨑睦男家住宅東蔵","kana":"かわさきむつおけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原5-3-10","lat":35.02603203,"lng":135.99682434,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"25 － 0031","desc":"主屋の右手，妻を東海道旧道にみせて建つ。軒蛇腹付きの標準的土蔵であるが，腰を縦板貼りとし，屋根は置屋根形式とする。比較的小規模な蔵であるが，主屋とともに街路景観の重要な構成要素になっており，屋敷構成の上でも欠くことのできない存在といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000539"},{"id":"00012180","register_sub_id":"101","register_pk":"352980","name":"川並家住宅主屋","kana":"かわなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡甲良町大字下之郷1494","lat":35.203574,"lng":136.256434,"geo_status":"db","era":"明治8年頃／昭和40年代改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積142㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-418","desc":"集落内の南西角地に南面して建つ。入母屋造茅葺（鉄板仮葺）で周囲に桟瓦葺の下屋を廻らす。右土間で、床上部は整型四間取で南面に廊下を通し、表列上手の座敷に床と仏間を備える。差物で柱を固め、建具も上質である。湖東・湖南地域の伝統形式を示す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012180"},{"id":"00012181","register_sub_id":"101","register_pk":"352981","name":"川並家住宅文庫蔵","kana":"かわなみけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡甲良町大字下之郷1494","lat":35.203672,"lng":136.256469,"geo_status":"db","era":"明治8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"25-419","desc":"主屋背面に東西棟で建ち、桁行五・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺。南面西寄りに戸口を開き主屋と接続する。外壁漆喰塗で、通りに面する西妻の上下階に窓を開けて銅板張の扉を開き、持送付の庇を付す。屋敷構えを引立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012181"},{"id":"00011975","register_sub_id":"101","register_pk":"211157","name":"川村家住宅主屋","kana":"かわむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市中央一丁目102","lat":35.009227,"lng":135.862632,"geo_status":"db","era":"大正12年／昭和36年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"25-399","desc":"大津旧市街地の中心、通称電車通に西面する。木造二階建、切妻造桟瓦葺の町家。当初は棒石鹸の販売等を行っており、玄関及び旧帳場を広く取る。床上部は奥の座敷前に四畳半と板間を取り、二階表側は洋室とする。屋根に起りを持たせた外観も特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011975"},{"id":"00008129","register_sub_id":"101","register_pk":"132527","name":"北川家住宅主屋","kana":"きたがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市京町1-403","lat":35.00726257,"lng":135.86382998,"geo_status":"db","era":"江戸末期／明治20年増築・大正期・昭和8年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0280","desc":"京町通りに北面する町家。間口１２ｍの２階建、切妻造桟瓦葺とし、正面に下屋を付設。トオリニワに一列三室形の平面で、質の高い書院座敷等を増築。真壁造で、上屋は東端に深緑色の竪格子をもつ虫籠窓を開け、下屋には平格子や出格子を設け、端正な表構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008129"},{"id":"00008130","register_sub_id":"101","register_pk":"132528","name":"北川家住宅土蔵","kana":"きたがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市京町1-403","lat":35.00703274,"lng":135.86374467,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0281","desc":"主屋の南奥、中庭を挟む位置に南北棟で建つ。切妻造妻入桟瓦葺、桁行５．８ｍ梁間４．４ｍの２階建土蔵。北面に出入口を設け、下屋を掛け、蔵前とする。切石積基礎上に建ち、外壁を漆喰仕上げとするが、北面には焼杉板を竪板張とする。町家に残る土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008130"},{"id":"00010476","register_sub_id":"101","register_pk":"202567","name":"北川家住宅土蔵","kana":"きたがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県守山市三宅町字里ノ内735-5","lat":35.057345,"lng":135.972171,"geo_status":"db","era":"江戸末期／大正頃移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"25 － 0356","desc":"志那街道沿いの集落内で、敷地北東隅に建つ。桁行六メートル規模で、土蔵造二階建、切妻造桟瓦葺とし、南西面に下屋を廻らす。外壁漆喰塗で北東面に腰高に竪板を張り、両妻面に開口を設ける。二尺近い成の棟木と母屋に流し板を張る特異な小屋形式をもつ土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010476"},{"id":"00009311","register_sub_id":"101","register_pk":"194104","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市長等2-809","lat":35.00964161,"lng":135.86171187,"geo_status":"db","era":"明治前期／昭和中期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0309","desc":"通り沿いのつし二階建町家で、建築面積九八平方メートル、切妻造桟瓦葺である。正面は出格子を設け、上部に虫籠窓を穿つ。内部は通土間沿いに三室を並べる形式で、出格子内側に建てる引戸など造作も旧規をよくとどめる。明治前期の大津町家の典型を示す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009311"},{"id":"00009312","register_sub_id":"101","register_pk":"194105","name":"木村家住宅土蔵","kana":"きむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市長等2-809","lat":35.00960116,"lng":135.86184393,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0310","desc":"主屋後方に西面して建つ土蔵。土蔵造二階建、桁行三・七メートル梁間三・四メートル、切妻造桟瓦葺で、西面に庇を付ける。外壁は軒まで漆喰で塗込め、高く竪板を張り、南妻面の上下階に小窓を穿つ。大津町家の伝統的な屋敷構成を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009312"},{"id":"00009631","register_sub_id":"101","register_pk":"194627","name":"旧石橋家住宅中蔵","kana":"きゅういしばしけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11","lat":35.26160921,"lng":136.25954617,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0339","desc":"東主屋の後方、東蔵の西隣に南北棟で並び建つ。切妻造桟瓦葺、妻入で、南面に戸口を開き、東蔵と一連の吹放しの下屋を差し掛ける。小屋は東蔵と異なり湾曲した梁で棟木を受ける。外壁は漆喰塗で腰に竪板を張る。東蔵とともに屋敷構えに趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009631"},{"id":"00009628","register_sub_id":"101","register_pk":"194624","name":"旧石橋家住宅中主屋","kana":"きゅういしばしけじゅうたくなかしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11-1","lat":35.26163539,"lng":136.25922495,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積185㎡","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0336","desc":"東主屋と西主屋の間に棟を揃えて建つ。木造平屋一部二階建、切妻造桟瓦葺で、二階を漆喰塗込とし袖うだつをあげる。西寄りに幅広の土間を通し、背後に広い台所を設ける。床上部は二列六室を並べ、前面に出格子をたて、駒寄せで囲む。風格ある構えをもつ町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009628"},{"id":"00009632","register_sub_id":"101","register_pk":"194628","name":"旧石橋家住宅西蔵","kana":"きゅういしばしけじゅうたくにしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11","lat":35.26170201,"lng":136.25946527,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積65㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0340","desc":"中主屋後方の敷地北西隅に東西棟で建ち、桁行六メートル梁間四メートル、土蔵造二階建、切妻造桟瓦葺で、東妻面を出入口とし、下屋を設ける。外壁は漆喰塗で腰に竪板を張り、二階両妻に小窓を穿ち、木枠で支持する庇を付ける。小屋は登り梁形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009632"},{"id":"00009629","register_sub_id":"101","register_pk":"194625","name":"旧石橋家住宅西主屋","kana":"きゅういしばしけじゅうたくにししゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市芹町11-1","lat":35.26170439,"lng":136.25917974,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0337","desc":"中主屋の西側に接続する。建ちの低い外観のつし二階建で、軒裏まで中塗で塗込め、中央に虫籠窓を穿つ。屋根は切妻造桟瓦葺で、西端に袖うだつを設ける。内部は中央に通土間をのばし、左右に居室を一列ずつ並べる。近世の彦根城下の佇まいを伝える町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009629"},{"id":"00009630","register_sub_id":"101","register_pk":"194626","name":"旧石橋家住宅東蔵","kana":"きゅういしばしけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11","lat":35.26156163,"lng":136.25956283,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0338","desc":"東主屋後方に、ほぼ同大の東蔵と中蔵が南北棟で東西に並び建つ。東蔵は、切妻造桟瓦葺、妻入で、南面に中蔵と一連の吹放しの下屋を差し掛ける。南正面西寄りに戸口を開き、小屋は洋小屋とする。外壁は漆喰塗で腰に竪板を張り、中蔵と外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009630"},{"id":"00009627","register_sub_id":"101","register_pk":"194623","name":"旧石橋家住宅東主屋","kana":"きゅういしばしけじゅうたくひがししゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11","lat":35.26147834,"lng":136.25935582,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積282㎡","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0335","desc":"通りに南面し、前面に二階建の表屋を構え、玄関と中庭を介して住居部を建てる。表屋は前面に出格子をたてて東端を土間とする。住居部は東寄りに土間を通し、居室は整型四間取で後方に風呂等を張出す。県内で数少ない表屋造形式の大型町家で造作も上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009627"},{"id":"00009633","register_sub_id":"101","register_pk":"194629","name":"旧石橋家住宅南蔵","kana":"きゅういしばしけじゅうたくみなみくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11-1","lat":35.26169012,"lng":136.25937961,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0341","desc":"中主屋後方の台所に接続して東西棟で建つ。桁行五・二メートル梁間四・一メートル、土蔵造二階建、切妻造桟瓦葺で、南面西寄りの戸口を土戸片引とし下屋を設ける。外壁は漆喰塗で腰に竪板を張り、二階東妻に窓を穿つ。主屋と一連の屋敷景観を創る小規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009633"},{"id":"00010182","register_sub_id":"101","register_pk":"198015","name":"旧一圓家住宅米蔵","kana":"きゅういちえんけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字一円字西角149","lat":35.235459,"lng":136.301155,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0351","desc":"主屋後方に東西棟で建つ。土蔵造二階建、桁行七・四メートル梁間三・八メートル、切妻造桟瓦葺で、西妻面に戸口を開き、庇を付ける。外壁は白色の鉄板張で鉢巻を廻らし、腰を横板張とし、二階西面に窓を穿つ。小屋は和小屋を組む。屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010182"},{"id":"00010180","register_sub_id":"101","register_pk":"198013","name":"旧一圓家住宅主屋","kana":"きゅういちえんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字一円字西角149","lat":35.235312,"lng":136.300951,"geo_status":"db","era":"安政4／明治24改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0349","desc":"敷地中央に西面して建つ。木造二階建、切妻造桟瓦葺で周囲に下屋を廻らす。外壁は黒漆喰塗で腰を下見板張とし、二階に横長の窓を並べる。平面は六間取系で、鍵の手に座敷を並べて要所に座敷飾を備え、正面中央に式台を構える。旧家の格式を伝える上質な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010180"},{"id":"00010183","register_sub_id":"101","register_pk":"198016","name":"旧一圓家住宅雑蔵及び木蔵","kana":"きゅういちえんけじゅうたくぞうぐらおよびきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字一円字西角149","lat":35.23522,"lng":136.301047,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0352","desc":"主屋の南側に接して東西棟で建つ。土蔵造二階建、桁行七・四メートル梁間三・八メートル、切妻造、置屋根式の桟瓦葺で、東妻面と南面に戸口を開く。外壁は漆喰塗で軒裏まで塗込める。内部は上下階とも一室で、二階に一階採光のための内開き窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010183"},{"id":"00010181","register_sub_id":"101","register_pk":"198014","name":"旧一圓家住宅文庫蔵","kana":"きゅういちえんけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字一円字西角149","lat":35.235423,"lng":136.300987,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0350","desc":"主屋北東隅の張出し部に接続し南北棟で建つ。土蔵造二階建、桁行六・〇メートル梁間四・〇メートル、切妻造桟瓦葺で、両妻面に戸口を開き、主屋のクチロウカから出入りする。壁は白色の鉄板張で鉢巻を廻らし、二階北面に窓を穿つ。内蔵として使用した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010181"},{"id":"00009637","register_sub_id":"101","register_pk":"194633","name":"旧石橋家住宅北塀","kana":"きゅうきゅういしばしけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11","lat":35.26167219,"lng":136.2595503,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長8.2m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0345","desc":"中蔵北西隅と西蔵北東隅の間をつなぐ塀。高さ三・五メートル、延長八・二メートル、切妻造桟瓦葺で、東寄りに一間幅の出入口を設けて板戸を吊る。北面は高く竪板を張り、小壁は中塗仕上げで木瓜形の窓を開け、腕木で軒を支持する。穏やかな印象になる高塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009637"},{"id":"00009636","register_sub_id":"101","register_pk":"194632","name":"旧石橋家住宅西塀","kana":"きゅうきゅういしばしけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11他","lat":35.26176558,"lng":136.25942556,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、延長28m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0344","desc":"敷地北西隅に矩折れにのびる塀で、高さ三・四メートル、延長二八メートル、切妻造桟瓦葺である。敷地外側は腰高に竪板を張り、小壁を漆喰壁とし、内側は低く腰板を張り、壁は中塗仕上げとして仕様を変える。屋敷地背面側の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009636"},{"id":"00009635","register_sub_id":"101","register_pk":"194631","name":"旧石橋家住宅庭塀","kana":"きゅうきゅういしばしけじゅうたくにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11他","lat":35.26163709,"lng":136.2593656,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、延長9.7m、潜戸付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0343","desc":"南蔵東面と中主屋北東角を折曲がりにつなぐ塀で、総延長九・七メートルを測る。北側は高さ二・五～三メートル、切妻造桟瓦葺で、腰板を張り、壁を漆喰塗とする。南側は大和塀形式で、中央に潜戸を開き、襷欄間を設ける。瀟洒なつくりの庭塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009635"},{"id":"00009634","register_sub_id":"101","register_pk":"194630","name":"旧石橋家住宅南塀","kana":"きゅうきゅういしばしけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市芹町11他","lat":35.2615473,"lng":136.25919485,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、総延長21m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0342","desc":"東主屋と中主屋の間、及び東主屋東側に矩折れにのびる塀である。高さ三・三メートル、総延長二一メートル、切妻造桟瓦葺で、東隣地境部分は棟高を下げる。外部は腰高に竪板を張り、小壁を真壁とし、漆喰などで仕上げる。旧家の表構えを引立てる高塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009634"},{"id":"00011330","register_sub_id":"101","register_pk":"209167","name":"旧佐藤家住宅主屋","kana":"きゅうさとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市芹中町1-1","lat":35.260829,"lng":136.257004,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積110㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0379","desc":"芹川沿いに所在する二階建町家。一階正面に鉄格子の出窓を設け、出桁造の二階は塗込めて瓦屋根の袖うだつを張出し、重厚な正面構えを見せる。内部は上下階の前面に洋室を配する他は座敷等とする。伝統形式を基調としつつ外観、平面ともに独自性豊かな近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011330"},{"id":"00010317","register_sub_id":"101","register_pk":"199090","name":"旧多田家住宅主屋","kana":"きゅうただけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市京町2-39","lat":35.006277,"lng":135.865618,"geo_status":"db","era":"明治中期／平成19年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"25-0355","desc":"旧市街地の小路に西面する間口三間半の町家。正面北寄りに戸口を開いて土間を通し、南側に出格子をたてて駒寄せで囲う。二階は竪格子窓を大きく開け、両端に袖壁を付ける。内部は一列四室形式で、出格子内側の引込み板戸などに、大津の町家の特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010317"},{"id":"00007364","register_sub_id":"101","register_pk":"108346","name":"旧田中家住宅（近江商人亭）大広間","kana":"きゅうたなかけじゅうたく（おうみしょうにんてい）おおひろま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町中宿字通町46-1他","lat":35.175369,"lng":136.210403,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0263","desc":"主屋の東方に、庭を挟んで建つ。木造平屋建、入母屋造桟瓦葺で、東・北・西面に下屋庇をまわし、南面に入母屋造の突出部を付ける。十畳座敷２室の三方に縁をまわし、周囲にガラス戸を建て、庭と一体的な空間をもつ。内部も良材を用いて丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007364"},{"id":"00007367","register_sub_id":"101","register_pk":"108349","name":"旧田中家住宅（近江商人亭）北土蔵","kana":"きゅうたなかけじゅうたく（おうみしょうにんてい）きたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町中宿字通町46-1他","lat":35.17551962,"lng":136.2100949,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0266","desc":"敷地の北隅、茶室の西面に接続する。桁行６．１ｍ梁間４．４ｍ、土蔵造２階建、切妻造桟瓦葺。外壁は漆喰仕上げで、腰の水切り下を竪板張とし、屋根は置屋根形式である。鉢巻に特徴的な欠眉をつけるなど、屋敷の西北隅にあって歴史的な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007367"},{"id":"00007365","register_sub_id":"101","register_pk":"108347","name":"旧田中家住宅（近江商人亭）茶室","kana":"きゅうたなかけじゅうたく（おうみしょうにんてい）しゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町中宿字通町46-1他","lat":35.175503,"lng":136.210144,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0264","desc":"主屋西北に雁行形に配し、西面を北土蔵と接続。桁行５．８ｍ梁間６．０ｍの平屋建、入母屋造桟瓦葺。東妻を庭側に見せ、落縁をつけて落ち着いた佇まいとする。内部は八畳間の北面を３分し、丸竹や松の落掛など多彩な銘木を用いて、トコまわりの意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007365"},{"id":"00007363","register_sub_id":"101","register_pk":"108345","name":"旧田中家住宅（近江商人亭）主屋","kana":"きゅうたなかけじゅうたく（おうみしょうにんてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町中宿字通町46-1他","lat":35.175407,"lng":136.210175,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積181㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0262","desc":"敷地中央に西面して建つ。切妻造桟瓦葺で南面に下屋庇を設ける。木造２階建一部平屋建、上・下階とも田の字型に座敷を配する。下階では南側を玄関とし、北側の座敷部は差物で柱を固める。また東・西面に縁を付け、庭側を開放的とするなど、上質なつくりの住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007363"},{"id":"00007366","register_sub_id":"101","register_pk":"108348","name":"旧田中家住宅（近江商人亭）南土蔵","kana":"きゅうたなかけじゅうたく（おうみしょうにんてい）みなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町中宿字通町46-1他","lat":35.175304,"lng":136.210251,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0265","desc":"主屋と大広間を繋ぐ廊下の南に接する蔵。桁行８．１ｍ梁間４．７ｍ、土蔵造２階建、切妻造妻入桟瓦葺。西面の出入口は漆喰塗の扉枠に植物紋の渦や家紋の「一升」を象り、東面妻壁では丸窓の上に唐破風状の漆喰塗庇を付けるなど、技巧的な左官仕事が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007366"},{"id":"00006402","register_sub_id":"101","register_pk":"107385","name":"旧中島家住宅主屋","kana":"きゅうなかじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市小野223-8","lat":35.01815486,"lng":136.00830807,"geo_status":"db","era":"明治初期／平成5移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、茅葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0247","desc":"桁行１３ｍ弱、梁間８ｍの規模で、入母屋造茅葺とし、四周に桟瓦葺の庇を設ける。内部は土間を左手に、右手を整形四間取の床上部とし、前寄り右端のオクノマに仏壇、その奥のナンドに縁を張る。湖東地方における標準的な中規模農家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006402"},{"id":"00014182","register_sub_id":"101","register_pk":"508812","name":"旧山口嘉七家住宅主屋","kana":"きゅうやまぐちかしちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1086","lat":35.01113889,"lng":136.25324722,"geo_status":"db","era":"文政3年(1820)／昭和14年増築","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積146㎡","structure_material":"木造平屋一部2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0508","desc":"日野町市街の通りに前庭を挟んで所在する商人住宅。つし二階建、切妻造桟瓦葺平入で、東側に二階建入母屋造を増築する。主屋の間取りは西側に土間を通し、東側に四間取畳敷きとその背面側に奥行一間の二室を配す。日野商人番頭の近世住宅で改造少なく貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014182"},{"id":"00014183","register_sub_id":"101","register_pk":"508813","name":"旧山口嘉七家住宅北蔵","kana":"きゅうやまぐちかしちけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1086","lat":35.01134167,"lng":136.25325,"geo_status":"db","era":"文政5年(1822)","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0509","desc":"日野商人の屋敷にある土蔵。主屋後方の敷地北西隅に位置する。土蔵造二階建、切妻造桟瓦葺平入、漆喰仕上鉢巻付で、戸前庇も塗り上げる。戸口に鳥居枠を飾り、掛子塗扉を建てる。内部は各階板間一室、中央に柱を立てる。主屋と共に屋敷の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014183"},{"id":"00014184","register_sub_id":"101","register_pk":"508814","name":"旧山口嘉七家住宅東蔵","kana":"きゅうやまぐちかしちけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字大窪1086","lat":35.01128889,"lng":136.25331111,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0510","desc":"日野商人屋敷の土蔵で、主屋後方に位置する南北棟で西面する。土蔵造二階建、切妻造桟瓦葺、漆喰仕上鉢巻付、腰板張とする。戸口に鳥居枠を飾り、掛子塗扉を建て、内部は各階板間一室。小屋組は太い曲梁に束立とする。主屋と共に屋敷の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014184"},{"id":"00015316","register_sub_id":"101","register_pk":"532440","name":"旧山根家住宅店舗兼主屋","kana":"きゅうやまねけじゅうたくてんぽけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市柏原字西町2202","lat":35.34091389,"lng":136.39716111,"geo_status":"db","era":"明治中期／平成20年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":null,"register_no":"25 - 0523","desc":"柏原宿の西寄りに位置する旧家の店舗兼主屋。中山道に北面して建つ、つし２階建切妻造平入桟瓦葺の主屋の東に入母屋造妻入の店舗棟を接続し、両棟の間を式台玄関とする。主屋は外壁漆喰塗で虫籠窓を開け、長大な間口の表構えが宿場の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015316"},{"id":"00013127","register_sub_id":"101","register_pk":"368283","name":"旧四居家住宅主屋","kana":"きゅうよついけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市元浜町131","lat":35.381625,"lng":136.26866667,"geo_status":"db","era":"江戸中期／平成21年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、金属板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0441","desc":"長浜市街にある油商を営んだ商家の主屋である。木造平屋建で通りに西面する比較的大規模な町家である。切妻屋根の両妻面に桟瓦葺の卯建を立上げる。建ちが低く、主要な柱を通し柱とし、差物の成が低いなど古式である。当地区の伝統的な形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013127"},{"id":"00008133","register_sub_id":"101","register_pk":"132531","name":"桐畑家住宅主屋","kana":"きりはたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央1-410","lat":35.00957458,"lng":135.86453288,"geo_status":"db","era":"明治中期／昭和前期・平成11年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0284","desc":"浜通りに北面して建つ。間口７．３ｍの木造２階建、切妻造桟瓦葺で正面に庇を付ける。西側をトオリニワとする一列四室の町家で、２階通り側には釣トコを備える座敷を配する。１階に出格子を構え、２階は出桁造の軒に半間毎に大斗肘木を飾る特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008133"},{"id":"00008135","register_sub_id":"101","register_pk":"132533","name":"桐畑家住宅土蔵","kana":"きりはたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央1-410","lat":35.00934802,"lng":135.86440526,"geo_status":"db","era":"正徳6年（1716）","year":1716,"year_source":"db","year_min":1716,"year_max":1716,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0286","desc":"離れの南奥、敷地南端に建つ。北面して建つ土蔵造２階建、切妻造本瓦葺。桁行６．４ｍ梁間６．０ｍで北西隅は軒先を含め角を欠く。北面に庇を掛け、出入口を穿つ。外壁は白漆喰仕上げで、高く竪板を張る。内部は土壁で土間床とする。江戸中期に遡る土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008135"},{"id":"00008134","register_sub_id":"101","register_pk":"132532","name":"桐畑家住宅離れ","kana":"きりはたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央1-410","lat":35.00947841,"lng":135.86447369,"geo_status":"db","era":"江戸末期／昭和中期・平成期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0285","desc":"中庭を挟み、主屋の南奥に位置する。東西棟の切妻造桟瓦葺で、中庭東に太鼓橋風の縁を架けて主屋に通じる。桁行５．３ｍ梁間６．７ｍの木造平屋建で、南北に２室を配し、東寄りに廊下、中庭側に縁を付設する。主屋、中庭、離れからなる町家構成を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008134"},{"id":"00002633","register_sub_id":"101","register_pk":"103623","name":"葛野常喜家住宅蔵","kana":"くずのじょうきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市葛川坊村町102","lat":35.246811,"lng":135.86795,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、鉄板葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0184","desc":"敷地の南西角に東面して建つ。２階建，土蔵造，平入，置屋根，桟瓦型鉄板葺で，戸口及び北妻面の２方に下屋を付す。小規模だが細部まで丁寧な造りで保存状態も良い。高く張った焼板と漆喰塗の対比が鮮やかな外観は明王院参道の景観形成の主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002633"},{"id":"00002632","register_sub_id":"101","register_pk":"103622","name":"葛野常喜家住宅主屋","kana":"くずのじょうきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市葛川坊村町102","lat":35.2468891,"lng":135.86806451,"geo_status":"db","era":"天保14","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積132㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0183","desc":"代々葛川明王院の信徒総代を務めた家で，若狭街道から参道へ入る角地に参道を挟んで旧政所葛野常満家に相対して建つ。入母屋造，茅葺（現在鉄板覆い）で農家の外観を呈するが，土間大戸脇には式台を構える。明王院門前集落の景観形成上欠かせない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002632"},{"id":"00002551","register_sub_id":"101","register_pk":"103541","name":"葛野常満家住宅蔵","kana":"くずのじょうまんけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市葛川坊村町92","lat":35.24665938,"lng":135.86792425,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"25 － 0182","desc":"主屋の北，参道に妻面を見せて建つ。平入，２階建，土蔵造，置屋根，桟瓦葺で，西面戸口に下屋を付して蔵前とする。小規模だが丁寧な造りで，高い焼板張の腰部と漆喰塗の対比が鮮やかな均整のとれた外観は，明王院参道の景観形成上，主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002551"},{"id":"00002550","register_sub_id":"101","register_pk":"103540","name":"葛野常満家住宅主屋","kana":"くずのじょうまんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市葛川坊村町92","lat":35.246574,"lng":135.867966,"geo_status":"db","era":"天保年間","year":1836,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積145㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"25 － 0181","desc":"葛川明王院の政所を務めた家で，若狭街道から参道へ入る角地にある。主屋は入母屋造，茅葺（現在鉄板覆い）で農家の外観を呈するが，通りニワをもつ平面や技巧的で堅牢な軸組は当地域に類例がなく特異である。明王院門前集落の景観形成上核となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002550"},{"id":"00010639","register_sub_id":"101","register_pk":"201213","name":"小泉家住宅裏門及び塀","kana":"こいずみけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町字南小路266","lat":35.141732,"lng":136.184456,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"裏門 木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長22m","structure_material":"裏門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"25－0373","desc":"敷地西面の南半を区画する門と塀。裏門は中央南寄りに位置する間口一間の腕木門、切妻造桟瓦葺で、南と北に延びる塀は、真壁造、腰を舟板竪張、上部に横連子欄間を入れ、桟瓦葺屋根を架ける。木部を弁柄塗とした丁寧なつくりで、屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010639"},{"id":"00010634","register_sub_id":"101","register_pk":"201208","name":"小泉家住宅大土蔵","kana":"こいずみけじゅうたくおおどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町266","lat":35.141875,"lng":136.1846,"geo_status":"db","era":"江戸末期／昭和13年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積72㎡、渡廊下及び塀付","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0368","desc":"洋館北側に東西棟で建つ切妻造桟瓦葺で、桁行六間梁間二間半、土蔵造二階建である。南面の東寄りを戸口として下屋の蔵前廊下を設ける。弁柄塗小庇付の窓、外壁頂部に廻した幅広の鉢巻、腰を覆う舟板など、重厚感のある土蔵で、屋敷北西部の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010634"},{"id":"00010638","register_sub_id":"101","register_pk":"201212","name":"小泉家住宅表門及び表塀","kana":"こいずみけじゅうたくおもてもんおよびおもてべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町字南小路270","lat":35.141798,"lng":136.185056,"geo_status":"db","era":"明治40年頃／昭和13年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"表門 木造、瓦葺、間口3.8m 表塀 木造、瓦葺、延長19m","structure_material":"表門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"25－0372","desc":"敷地の北東隅、一間薬医門で切妻造桟瓦葺の表門が北面して建ち、東西に延びる矩折れの表塀が西に潜戸、東は直角に南へ折れて納屋に達する。真壁造の表塀は腰を舟板竪張、桟瓦葺とする。調和のとれた意匠の門塀で、屋敷に相応しい表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010638"},{"id":"00010635","register_sub_id":"101","register_pk":"201209","name":"小泉家住宅米蔵","kana":"こいずみけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町266","lat":35.141932,"lng":136.184653,"geo_status":"db","era":"江戸末期／昭和13年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡、塀付","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0369","desc":"敷地北西隅に東西棟で建つ。桁行三間梁間二間、土蔵造二階建で置屋根式切妻造の桟瓦葺とする。南面の観音開きの戸口と各面小窓に銅板葺の庇を付ける。漆喰塗外壁の腰を舟板で覆うが、柱から壁までの内部を中塗仕上げとする。屋敷北西隅の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010635"},{"id":"00010631","register_sub_id":"101","register_pk":"201205","name":"小泉家住宅小家蔵","kana":"こいずみけじゅうたくこやぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141832,"lng":136.184914,"geo_status":"db","era":"天保15年（1844）／明治40年移築","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0365","desc":"主屋の北側に隣接して東西棟で建つ。桁行五間梁間二間の細長い二階建土蔵造で、切妻造桟瓦葺で、各面の窓には小庇を付ける。軒裏まで漆喰塗とし、通りに面した腰を舟板で覆い、内部に水路作業用の石組を構えるなど、当地方の建築的特色を具備している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010631"},{"id":"00010627","register_sub_id":"101","register_pk":"201201","name":"小泉家住宅座敷棟","kana":"こいずみけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.14167,"lng":136.184894,"geo_status":"db","era":"慶応2年（1866）頃／明治40年移築・大正期改修","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0361","desc":"主屋南東隅に接続する木造平屋建、屋根は東西棟の切妻造桟瓦葺で三方に庇を廻す。西寄より六畳、床と平書院付の八畳、辰巳蔵に面したクラマエからなる平面で、両側に縁を設ける。簡明なつくりの接客施設であるが、主屋と一体となって屋敷中枢をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010627"},{"id":"00010637","register_sub_id":"101","register_pk":"201211","name":"小泉家住宅下便所及び中門","kana":"こいずみけじゅうたくしもべんじょおよびちゅうもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141682,"lng":136.184989,"geo_status":"db","era":"大正4年頃／昭和前期改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"下便所 木造平屋建、瓦葺、建築面積5.8㎡、板塀付 中門 木造、瓦葺、間口2.0m、袖塀付","structure_material":"下便所 木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0371","desc":"主屋の桁行中央南寄りの東にあり、前庭と中庭を分節している。下便所は桁行一間半梁間一間の平屋建真壁造、両側袖塀付の中門は一間腕木門で、ともに東西棟の切妻造桟瓦葺である。吟味された良材による瀟洒な数寄屋意匠で、屋敷の空間構成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010637"},{"id":"00010626","register_sub_id":"101","register_pk":"201200","name":"小泉家住宅主屋","kana":"こいずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141751,"lng":136.184918,"geo_status":"db","era":"天保15年(1844)／明治40年移築・大正4年頃改修","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡、塀付","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0360","desc":"敷地北側の東寄り、東面して建つ木造二階建で、南北棟の切妻造を立ち上げて四面に庇を廻し、桟瓦葺とする。一階は北側に土間を配した整形四間取平面で、二階にも座敷飾の整った居室をもつ。近江商人の居宅に相応しい雄大な規模で、屋敷景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010626"},{"id":"00010629","register_sub_id":"101","register_pk":"201203","name":"小泉家住宅小洋館及び丁稚部屋","kana":"こいずみけじゅうたくしょうようかんおよびでっちべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.14177,"lng":136.184775,"geo_status":"db","era":"明治42年頃／昭和前期・昭和13年頃増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0363","desc":"主屋背面にある東西に細長い建物。主屋寄りが小洋館で、廊下を挟んで西に六畳と七畳半の丁稚部屋が続いている。小洋館は主屋の上便所を巧妙に洋室へ改造、西端が増築部。中央部の入母屋造から両側に棟を延ばした複雑な桟瓦葺で、施設拡充の変遷を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010629"},{"id":"00010628","register_sub_id":"101","register_pk":"201202","name":"小泉家住宅新座敷棟","kana":"こいずみけじゅうたくしんざしきとう","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141575,"lng":136.18496,"geo_status":"db","era":"大正期／昭和前期改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積62㎡、塀付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0362","desc":"敷地東辺の南寄りにあり、座敷棟と接続している。木造平屋建、南北棟の桟瓦葺で、南を入母屋、北を切妻とし、南塀が附属する。南の踏込み床に付書院を備える八畳座敷と北の六畳間が当初で、辰巳蔵間のイタノマは増築。近代における邸宅の拡充を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010628"},{"id":"00010632","register_sub_id":"101","register_pk":"201206","name":"小泉家住宅辰巳蔵","kana":"こいずみけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141629,"lng":136.18501,"geo_status":"db","era":"天保15年（1844）／明治40年頃・昭和前期移築","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0366","desc":"中庭を挟んだ主屋の東向かいに南北棟で建つ。桁行三間梁間二間半の土蔵造二階建で、腰を舟板で覆い、置屋根式の切妻造桟瓦葺である。外観は簡素であるが、座敷クラマエに扉口を構え、一室の内部は丁寧なつくりになる。屋敷構成を知るうえで欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010632"},{"id":"00010636","register_sub_id":"101","register_pk":"201210","name":"小泉家住宅納屋","kana":"こいずみけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141697,"lng":136.185064,"geo_status":"db","era":"明治40年頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡、塀付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0370","desc":"主屋の東に対面して建つ、桁行四間半梁間一間半の平屋建真壁造。内部は土間で、桁行の北一間半は物置で精米所も兼ね、南三間は柴入れであった。南北棟の切妻造桟瓦葺で、西面に扉口二か所を設け、外壁の腰は舟板竪張とする。屋敷東辺の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010636"},{"id":"00010633","register_sub_id":"101","register_pk":"201207","name":"小泉家住宅文庫蔵","kana":"こいずみけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町270","lat":35.141854,"lng":136.184814,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積72㎡、塀付","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0367","desc":"桁行六間梁間二間半、土蔵造二階建で、屋敷北辺中央に建つ。南北棟の切妻造、東面南半に吹放し下屋を設け、桟瓦葺とする。観音開扉の開口部や内部仕上げなど丁寧な施工になり、漆喰塗の外壁頂部に鉢巻を廻して腰を舟板で覆う。年代も明確で邸宅の盛期を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010633"},{"id":"00010630","register_sub_id":"101","register_pk":"201204","name":"小泉家住宅洋館","kana":"こいずみけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘山本町266","lat":35.141825,"lng":136.184579,"geo_status":"db","era":"明治39年頃／昭和13年頃改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"25－0364","desc":"敷地西辺中央にある木造二屋建、南北棟の桟瓦葺、南を入母屋、北を切妻とし、西面に下屋を設ける。タイル張外壁、階境のスパニッシュ瓦の水切、上下窓の一階に比べ、二階は和風の軸組に両開の扉とガラス戸程度で、導入時期の異なる洋風意匠が共存している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010630"},{"id":"00000354","register_sub_id":"101","register_pk":"132552","name":"五個荘町歴史民俗資料館（旧藤井家住宅）石橋","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）いしばし","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市宮荘町681-2地先","lat":35.15793904,"lng":136.18958727,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造，幅4.8〜5.8m，長さ1.2m","structure_material":"石造","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0014","desc":"湖東地方に特徴的な集落内の水路に面した屋敷地に架かる石橋。長さ１．２ｍと短いが，前面幅５．８ｍ，後面幅４．８ｍとハの字型とし接道部分を広くしている。小規模ながら円形の造形になる高欄親柱付きの小橋として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000354"},{"id":"00000356","register_sub_id":"101","register_pk":"132554","name":"五個荘町歴史民俗資料館（旧藤井家住宅）内塀","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）うちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市宮荘町681・681-2","lat":35.15785231,"lng":136.18927193,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造，瓦葺，延長30.3m，棟門附属","structure_material":"木造","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0016","desc":"主屋を囲う木造の屋根塀で，化粧棟から北土蔵間を矩折れに結ぶ。東面は真壁，桟瓦葺とするが，北面は板塀で棟に瓦を載せた簡素な造りになる。化粧棟の北脇に小型の一間棟門を開く。延長３０ｍあり，屋敷地内の内向き部分を画する塀として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000356"},{"id":"00000352","register_sub_id":"101","register_pk":"101342","name":"五個荘町歴史民俗資料館（旧藤井家住宅）北土蔵","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）きたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市宮荘町681","lat":35.15790659,"lng":136.18910848,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積21㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0012","desc":"切石積の基礎上に建つ２階建ての小規模土蔵で，屋根は置き屋根形式になる。外壁は漆喰仕上げとするが，腰下に和船の舟板を横張りする点は特徴的である。主屋と一連に昭和９年頃現在地に移築されたもので，屋敷構えを構成する一要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000352"},{"id":"00000348","register_sub_id":"101","register_pk":"101338","name":"五個荘町歴史民俗資料館（旧藤井家住宅）主屋","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市宮荘町681","lat":35.15779511,"lng":136.18909118,"geo_status":"db","era":"明治初期／明治32座敷増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建，瓦葺，建築面積258㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0008","desc":"近江商人の旧宅を町立歴史民俗資料館としたもの。昭和７年に現在地に移築された主屋は，差鴨居で固めた四間取りの居室部に座敷２室を付加した平面を基本とする質素な造作になる。家具調度品とも保存され，質実剛健な気風の近江商人の生活を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000348"},{"id":"00000355","register_sub_id":"101","register_pk":"132553","name":"五個荘町歴史民俗資料館（旧藤井家住宅）外塀","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）そとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市宮荘町681・681-2","lat":35.15779461,"lng":136.18948495,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造・コンクリート造，延長113.9m，石造門柱・鉄製門扉附属","structure_material":"石造・コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0015","desc":"屋敷地の北面及び東面の一部を囲うコンクリート製の塀で，基底部や隅柱など要所を石製とする。北面に正門である鉄製の門扉付きの石造門を設ける。集落内に板塀や土塀が多いなかで、石造門付きのコンクリート塀は珍しく，時代の様相をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000355"},{"id":"00000353","register_sub_id":"101","register_pk":"101343","name":"五個荘町歴史民俗資料館（旧藤井家住宅）南土蔵","kana":"ごかしょうちょうれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）みなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市宮荘町681-2","lat":35.15759047,"lng":136.18910328,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積28㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"25 － 0013","desc":"表門の脇に位置し，切石積の基礎上に建つ２階建ての土蔵。規模は北土蔵より一回り大きい。全体的に簡素な外観になるが，漆喰仕上げの外壁の腰下には妻側は縦板を張り，庭に面する東側面は開口部を挟んで杉皮を縦張するなど意匠に工夫が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000353"},{"id":"00002635","register_sub_id":"101","register_pk":"103625","name":"五個荘町歴史民俗資料館（旧藤井家住宅）渡廊下","kana":"ごかしょうまちれきしみんぞくしりょうかん（きゅうふじいけじゅうたく）わたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市宮荘町681-2","lat":35.157694,"lng":136.18913413,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0186","desc":"五個荘町のほぼ中心に位置する近江商人の旧邸宅内の主屋と客殿を繋ぐ渡廊下。幅約４尺，長さ４間，屋根桟瓦葺で，内部は小丸太の垂木，長枌板を用いた化粧屋根裏天井，壁は色土壁とする。付属施設だが瀟洒な意匠をもち，屋敷の構えに欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002635"},{"id":"00015468","register_sub_id":"101","register_pk":"533483","name":"坂田家住宅主屋","kana":"さかたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市小野字村ノ内1144-1","lat":35.15199167,"lng":135.92211667,"geo_status":"db","era":"天保9年（1838）／昭和40年・平成28年改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"25 - 0524","desc":"北国街道沿いに位置する旧地主の主屋。通りに東面して建つ、つし二階建切妻造平入桟瓦葺で北面に平屋の納戸を附属。内部は南を土間、北に居室を並べ、北西に座敷を配す。一階は出格子構え、二階は出格子窓と虫籠窓を開け、街道沿いの歴史的景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015468"},{"id":"00000734","register_sub_id":"101","register_pk":"101724","name":"里内家住宅中蔵","kana":"さとうちけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原3-4-31","lat":35.02607654,"lng":136.00062603,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積26㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0046","desc":"離れの後方に建つ２階建の小規模な土蔵。明治５年に分家して呉服商をはじめたときに主屋等とともに建てられたと伝える。町内では旧東海道に面した商家の数は減少しており，その屋敷構えを示す建物のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000734"},{"id":"00000735","register_sub_id":"101","register_pk":"101725","name":"里内家住宅北蔵","kana":"さとうちけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原3-4-31","lat":35.02607654,"lng":136.00062603,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積69㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0047","desc":"中蔵の後方，屋敷地の北西隅に建つ平屋建の土蔵。もと米蔵で，主屋，中蔵等と同時期のものと伝え，屋敷構えの主要な構成要素となっている。腰に板を張るなど，意匠は中蔵とほぼ共通するが，正面・側面に吹き放しの庇をもうける点に違いがみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000735"},{"id":"00000732","register_sub_id":"101","register_pk":"101722","name":"里内家住宅主屋","kana":"さとうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市手原3-4-31","lat":35.02607654,"lng":136.00062603,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建一部２階建，瓦葺，建築面積202㎡","structure_material":"木造平屋建一部２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0044","desc":"呉服商を営んだ家で，旧東海道に面して屋敷を構える。主屋は，接道して建つ町家で，２階を低く押さえた外観など，明治初期の町家の特徴をよくそなえる。庇を正面から西側面に矩の手にまわし，上部に雨除けの小庇を設けるなど妻の意匠に工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000732"},{"id":"00000733","register_sub_id":"101","register_pk":"101723","name":"里内家住宅離れ","kana":"さとうちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県栗東市手原3-4-31","lat":35.02607654,"lng":136.00062603,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造２階建，瓦葺，建築面積86㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0045","desc":"主屋の背面西寄りに増築された２階屋。商家の生活の変化の様子を示した建物で，トコ・棚・書院を備えた座敷などの主室を２階におく点に主屋との年代の違いがあらわれている。座敷の意匠を主屋の座敷とかえるなど，細かな配慮もみることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000733"},{"id":"00008136","register_sub_id":"101","register_pk":"132534","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央2-6","lat":35.00748726,"lng":135.86713246,"geo_status":"db","era":"天保9年(1838)／昭和9年頃・平成期改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0287","desc":"中町通りに南面する、間口８．１ｍの木造２階建の町家。切妻造桟瓦葺で庇を付設。西に一列四室の居室を配し、東は正面から土間のオモテ、ナカニワ、ニワと続くが、ナカニワ部分は屋根がなく、表屋造風に造る。２階座敷に縁がまわり込むなど特徴的な構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008136"},{"id":"00008137","register_sub_id":"101","register_pk":"132578","name":"佐野家住宅土蔵","kana":"さのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央2-6","lat":35.0075973,"lng":135.867191,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造3階建、瓦葺、建築面積20㎡","structure_material":"土蔵造3階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0288","desc":"主屋オクザシキの北奥、中庭を挟み、切石基礎上に建つ。南北棟の切妻造妻入桟瓦葺。桁行５．４ｍ梁間３．７ｍの３階建土蔵。南面は１階に大和張板庇付の出入口を開け、掛子塗の両開戸を吊り、２、３階には瓦庇付の窓を穿つ。内部は杉板張の丁寧な仕上げになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008137"},{"id":"00012167","register_sub_id":"101","register_pk":"352967","name":"志賀谷家住宅主屋","kana":"しがやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市本町三丁目30","lat":35.272055,"lng":136.249547,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積137㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"25-405","desc":"旧職人町に位置する町家。木造二階建、切妻造桟瓦葺平入で、正面二階には袖壁を設ける。当初は通り土間に床上部二列六室であったと考えられ、小屋は中心部を和小屋として、その前方後方に登梁をかける。かつての城下の景観を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012167"},{"id":"00001627","register_sub_id":"101","register_pk":"102617","name":"珠玖家住宅蔵","kana":"しくけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市西中野町3-14","lat":35.10763421,"lng":136.19426,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0132","desc":"主屋の背面中央に隣接する東西棟の蔵。大壁造，白漆喰塗り，二階建で，屋根は，切妻造，桟瓦葺の置屋根とする。主屋に面する東妻を正面とし，一階に土戸，二階に鉄格子窓を設ける。小屋組は湾曲した大梁を用いて直接母屋を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001627"},{"id":"00013272","register_sub_id":"101","register_pk":"366261","name":"柴山家住宅","kana":"しばやまけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央一丁目115-4","lat":35.00785556,"lng":135.86356389,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0452","desc":"通りから折曲りにのびる小路に東面する二戸一棟の二階建長屋北半部。間口がやや広く、一階前面に格子を建て、二階も広いガラス窓とする。上下階とも真壁造で上階軒は出桁造の軒天にケヤキ板を張る。内部も床に数寄屋意匠を加味するなど大津長屋の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013272"},{"id":"00013273","register_sub_id":"101","register_pk":"366262","name":"清水家住宅主屋","kana":"しみずけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市観音寺90-7","lat":35.01565,"lng":135.85915,"geo_status":"db","era":"大正15年／平成29年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積90㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0453","desc":"旧琵琶湖西岸の敷地に建ち、二戸一棟の長屋の一軒分が残る。南正面の玄関の西側に勝手口と土間を配し、琵琶湖側の東列を正面入母屋造として座敷を並べ、縁を廻らす。二階も東側に座敷を並べる。各室の座敷飾や欄間も洗練される。戦前の上質な長屋建築の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013273"},{"id":"00013580","register_sub_id":"101","register_pk":"504943","name":"松樹館表門及び塀","kana":"しょうじゅかんおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15308611,"lng":136.18738333,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"表門 木造、瓦葺、間口1.8m、塀 木造、瓦葺、総延長136m","structure_material":"表門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0468","desc":"表門は敷地北辺の通りから九・五メートル奥まって建ち、屋根は切妻造桟瓦葺。表側に格子戸、内側に板戸の引分戸を建て、両脇を壁とする。塀は木造瓦葺で敷地外周及び表門と主屋間に建つ。広大な敷地をもつ近江商人の本宅における重要な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013580"},{"id":"00013569","register_sub_id":"101","register_pk":"504932","name":"松樹館主屋","kana":"しょうじゅかんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15292778,"lng":136.18724722,"geo_status":"db","era":"文化11年(1814)／平成27年改修","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積114㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0457","desc":"五個荘に建つ近江商人の旧宅の主屋。平面は西に土間を通し食違四間取形式で比較的規模が大きい。小屋組は扠首構造で補強に上下二段の貫を桁行に通す希少な例とする。農家型の近江商人の本宅の典型例で、勝元鈍穴の作庭になる広大な庭園が建物と一体に残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013569"},{"id":"00013581","register_sub_id":"101","register_pk":"504944","name":"松樹館カワト","kana":"しょうじゅかんかわと","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15313889,"lng":136.18745833,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、面積8.0㎡","structure_material":"石造","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0469","desc":"敷地北辺の通り沿いに位置する。建屋は無く、通りに並行して流れる川に面して、花崗岩の切石で囲み、石段を設けた洗い場で、川に対して取水口と排水口を設けて水を引き込む。広大な敷地をもつ近江商人の本宅における構成要素の一つで屋敷構えの一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013581"},{"id":"00013576","register_sub_id":"101","register_pk":"504939","name":"松樹館北蔵","kana":"しょうじゅかんきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15298333,"lng":136.18720556,"geo_status":"db","era":"寛政12年(1800)／江戸末期改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0464","desc":"主屋の西側に水屋を介して建つ。土蔵造二階建、桁行一間半余り、梁間二間、南北棟の切妻造で桟瓦葺とする。北側部分を切り縮めて規模縮小した。外壁は漆喰塗、軒裏塗込とする。南に蔵前がつき、戸口に漆喰塗の両開土戸を建てる。屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013576"},{"id":"00013578","register_sub_id":"101","register_pk":"504941","name":"松樹館米蔵","kana":"しょうじゅかんこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15307778,"lng":136.18719444,"geo_status":"db","era":"万延元年(1860)","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0466","desc":"敷地西辺で主屋の北西側に建つ。土蔵造二階建、桁行四間、梁間二間半、南北棟の切妻造で桟瓦葺の置屋根とする。外壁は一階竪板張、二階漆喰塗とする。戸口に漆喰塗の両開土戸を建てる。敷地内の土蔵五棟のうちの一つで近江商人の本宅の屋敷構えの一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013578"},{"id":"00013577","register_sub_id":"101","register_pk":"504940","name":"松樹館新蔵","kana":"しょうじゅかんしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.153,"lng":136.18713056,"geo_status":"db","era":"慶応元年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0465","desc":"敷地西辺で主屋の西側に建つ。土蔵造二階建、桁行四間、梁間三間、南北棟の切妻造で桟瓦葺の置屋根とする。外壁は漆喰塗、鉢巻を廻し戸口に漆喰塗の両開土戸を建てる。内部は丁寧に製材した簡素な造り。近江商人の本宅の屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013577"},{"id":"00013570","register_sub_id":"101","register_pk":"504933","name":"松樹館新建","kana":"しょうじゅかんしんだち","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15285833,"lng":136.18733889,"geo_status":"db","era":"明治6年／大正前期改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積83㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0458","desc":"主屋東側に接続する。主屋の床より一段高くし、襖戸を建て意匠を凝らした欄間を設けたジョウダンノマを構え、床の間と双折戸付仏壇を設ける。段階的に増築された二階建で、大正十三年の久邇宮家の御成りの儀に向けて整えたとされる格式ある内部空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013570"},{"id":"00013571","register_sub_id":"101","register_pk":"504934","name":"松樹館新寮","kana":"しょうじゅかんしんりょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15285833,"lng":136.1872,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0459","desc":"主屋ニワ南側に接続する。南北に長い十二畳の広さの部屋で、天井は南北二面に等分し、折上格天井を模した二段の天井とする。西面中央部には壁面から張出して、幅一間の流しを設け、四口の蛇口が付く。用途は不詳であるが、屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013571"},{"id":"00013579","register_sub_id":"101","register_pk":"504942","name":"松樹館長屋","kana":"しょうじゅかんながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15286667,"lng":136.18700556,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0467","desc":"敷地南西隅の外周の塀を利用し、内側に柱を立て片流れ及び切妻造の瓦屋根を架けた平面がＬ字形の物置。塀上部は瓦二枚分の小屋根を載せ保護する。塀部分の柱は細く、内側の柱は太い転用材で、塀以外に壁はなく、開放的な造りとする。屋敷構えの一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013579"},{"id":"00013574","register_sub_id":"101","register_pk":"504937","name":"松樹館文庫蔵","kana":"しょうじゅかんぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15272222,"lng":136.1873,"geo_status":"db","era":"文政12年(1829)","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0462","desc":"主屋の南東側に建つ。土蔵造二階建、桁行四間半、梁間二間半、南北棟の切妻造で桟瓦葺の置屋根とする。外壁は漆喰塗で鉢巻を廻し、戸口に漆喰塗の両開土戸を建てる。内部は丁寧に製材した簡素な造り。南蔵と並び主屋後方の屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013574"},{"id":"00013572","register_sub_id":"101","register_pk":"504935","name":"松樹館水屋","kana":"しょうじゅかんみずや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15293889,"lng":136.18717778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0460","desc":"主屋西側の土間部分に接続する。南半部は主屋ニワを西側に拡張して一連の大空間とする。花崗岩切石を一面敷き詰めた土間に流しや井戸を設け、南側に二基の竈を配する。南東隅部に床板張のイタノマを設け、往時の生活の様相を伝える。屋敷構えの一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013572"},{"id":"00013575","register_sub_id":"101","register_pk":"504938","name":"松樹館南蔵","kana":"しょうじゅかんみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15274444,"lng":136.187225,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0463","desc":"主屋の南側に建ち、廊下座敷に接続する。土蔵造二階建、桁行三間、梁間二間、南北棟の切妻造、北面妻入で桟瓦葺の置屋根とする。外壁は漆喰塗とし、北に蔵前がつき、戸口に漆喰塗の両開土戸を建てる。文庫蔵と並び主屋後方の屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013575"},{"id":"00013573","register_sub_id":"101","register_pk":"504936","name":"松樹館廊下座敷","kana":"しょうじゅかんろうかざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市五個荘竜田町字元屋敷396-1","lat":35.15279722,"lng":136.18726389,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0461","desc":"主屋南側に建ち、新建に接続して南蔵に通じる。八畳の座敷で、南西隅に釣床を設け、横には鼓形の下地窓を開ける。中庭に面する西面に切目縁の濡縁を廻してガラス障子を建て、小壁に意匠を凝らした欄間を設ける。庭との関係を重視した数寄屋風の造りの建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013573"},{"id":"00011978","register_sub_id":"101","register_pk":"211113","name":"角田家住宅米蔵","kana":"すみだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県米原市米原字中町通573","lat":35.315125,"lng":136.293185,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"25-402","desc":"主屋後方に東西棟で建ち、桁行五・九メートル梁間三・八メートル、土蔵造二階建、切妻造桟瓦葺である。東妻面の戸口廻りに漆喰仕上げの扉枠をつくり、楣に若葉付の絵様を表す。南面は腰を竪板張とし、二階に小窓を穿つ。主屋背後の庭空間を引き立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011978"},{"id":"00011977","register_sub_id":"101","register_pk":"211112","name":"角田家住宅主屋","kana":"すみだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県米原市米原字中町通573","lat":35.315029,"lng":136.293385,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"25-401","desc":"旧北国街道に東面する間口六間半の町家。つし二階建で正面に下屋を設け、出格子や虫籠窓を配し、袖壁を付ける。平面は南寄りを土間とし、居室は二列構成で、上手奥の一二畳主室に床を設ける。軸部は木太く豪壮にみせる。近世の米原宿の面影を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011977"},{"id":"00011979","register_sub_id":"101","register_pk":"211114","name":"角田家住宅文庫蔵","kana":"すみたけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市米原字中町通573","lat":35.31518,"lng":136.293223,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"25-403","desc":"米蔵の北隣に南北棟で建ち、桁行六・八メートル梁間三・七メートル、土蔵造二階建、切妻造桟瓦葺である。外壁漆喰塗で、置屋根の軒先まで塗籠める。東面南寄りに戸口を開いて庇を付け、扉枠の楣に、鏝絵で波間を渡る千鳥を表す。上質な左官仕事になる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011979"},{"id":"00016402","register_sub_id":"101","register_pk":"536469","name":"せんなり亭多賀別邸（旧石田家住宅）座敷棟","kana":"せんなりていたがべってい（きゅういしだけじゅうたく）ざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀字本町626","lat":35.22463333,"lng":136.28936667,"geo_status":"db","era":"昭和10年頃／令和3年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積54㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0533","desc":"多賀大社の門前町に位置する宮大工の旧宅の座敷棟。敷地東側に面する建ちの高い二階建桟瓦葺で、東は入母屋造、西は切妻造とする。各階二室で北室を床構え付き座敷とし、三方に縁を廻らす。二階北面は手摺を付して多賀道を望み、門前町の風情を伝える座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016402"},{"id":"00016403","register_sub_id":"101","register_pk":"536470","name":"せんなり亭多賀別邸（旧石田家住宅）門及び塀","kana":"せんなりていたがべってい（きゅういしだけじゅうたく）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀字本町626","lat":35.22470556,"lng":136.28939444,"geo_status":"db","era":"昭和10年頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、延長13m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0534","desc":"座敷棟の北に建つ門と両脇に続く高塀。塀は延長１３メートル、腕木で軒を支え屋根桟瓦葺。外壁漆喰塗で上部に格子窓を開け、腰は竪板張とする。東寄りに開く門口は銅板葺の腕木庇を付し、引分戸を建てる。座敷棟とともに門前町の景観をつくる瀟洒な門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016403"},{"id":"00000445","register_sub_id":"101","register_pk":"101435","name":"泰山閣（旧松居家住宅）表門","kana":"たいざんかく（きゅうまついけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市下一色町361-1","lat":35.15109056,"lng":136.2404497,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造棟門，瓦葺","structure_material":"木造棟門","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0026","desc":"屋敷地の南東隅に道路に南面して建つ棟門形式の門。北は広い庭を介して主屋玄関に通じる。屋根は桟瓦葺で、端部を銅板で葺き，全体にむくりをつける数寄屋風の意匠で，軽快な意匠は主屋と共通する。大工は施主の大阪の商人に出入りの木村太兵衛。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000445"},{"id":"00014488","register_sub_id":"101","register_pk":"513902","name":"土山家住宅（土山宿本陣跡）主屋","kana":"つちやまけじゅうたく（つちやましゅくほんじんあと）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"滋賀県","address":"滋賀県甲賀市土山町北土山字針ノ木原1628他","lat":34.93491667,"lng":136.28233611,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"25 - 0511","desc":"東海道の土山宿に南面して建つ主屋。2階建切妻造平入桟瓦葺の東西棟で、一階は出格子構え、二階は虫籠窓を開け、外壁は黒漆喰塗仕上。内部は東を土間、西に3列７室を配する。正面側柱に前身本陣の柱や虹梁型差物を用い、かつての本陣の表構えを伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014488"},{"id":"00014491","register_sub_id":"101","register_pk":"513905","name":"土山家住宅（土山宿本陣跡）米蔵","kana":"つちやまけじゅうたく（つちやましゅくほんじんあと）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市土山町北土山字針ノ木原1628他","lat":34.9353,"lng":136.28256111,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"25 - 0514","desc":"敷地北東隅に西面し、米を収納する蔵。平屋建切妻造平入桟瓦葺で西に戸口を設けて下屋を付す。板を積み上げたいわゆる井籠蔵で外壁は土壁で塗込め縦板張とする。内部は一室の板敷で、北に小窓を一箇所開ける。敷地北東の歴史的景観をつくる貴重な構造の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014491"},{"id":"00014490","register_sub_id":"101","register_pk":"513904","name":"土山家住宅（土山宿本陣跡）土蔵","kana":"つちやまけじゅうたく（つちやましゅくほんじんあと）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市土山町北土山字針ノ木原1628他","lat":34.93533889,"lng":136.28231667,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"25 - 0513","desc":"敷地北西隅に東面し、家財を収納する土蔵。二階建切妻造平入で、屋根は置屋根形式の桟瓦葺とする。東に戸口を二箇所設け、窓を西に四箇所、北に二箇所開ける。内部一階は南北二室で北室南に階段を設け、二階は一室とする。敷地北西の歴史的景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014490"},{"id":"00014489","register_sub_id":"101","register_pk":"513903","name":"土山家住宅（土山宿本陣跡）離れ","kana":"つちやまけじゅうたく（つちやましゅくほんじんあと）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県甲賀市土山町北土山字針ノ木原1628他","lat":34.93509722,"lng":136.28232778,"geo_status":"db","era":"明治後期／大正後期・昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"25 - 0512","desc":"主屋の北背面に庭を介して建つ離れ。平屋建、切妻造桟瓦葺で、北西に便所、南東に主屋に至る渡り廊下を附属する。内部は二列四室として北面と南面に縁を付して庭を臨む。北西室は床高を上げ、西に大床を構えた御上段の間とし、本陣の離れ座敷の形式を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014489"},{"id":"00010178","register_sub_id":"101","register_pk":"198011","name":"寺村家住宅主屋","kana":"てらむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市鳥居本町字立町664","lat":35.284367,"lng":136.284155,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0347","desc":"寄棟造桟瓦葺の木造住宅で、玄関上部に飾る切妻破風と二階正面に格子窓を穿つ。玄関脇に洋風意匠の応接間を設けて煙突を立て、後方は中廊下沿いに座敷などの居室を配する。和室中心の住宅だが、応接間や階段廻りなどをヴォーリズらしい瀟洒な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010178"},{"id":"00008303","register_sub_id":"101","register_pk":"133945","name":"百々家住宅主屋","kana":"どどけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市鳥居本町1804","lat":35.27895974,"lng":136.28282459,"geo_status":"db","era":"江戸末期／昭和6年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"25 － 0292","desc":"旧中山道に西面した敷地の南寄りに建ち、建築面積１４４㎡、木造つし２階、切妻造桟瓦葺である。正面は南側を通り土間の出入口とし、北側は出格子と駒寄せをたてる。上屋は出桁造で漆喰を塗り込め、虫籠窓を穿つ。街道筋に建つ旧家の表構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008303"},{"id":"00009313","register_sub_id":"101","register_pk":"194106","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央1-208","lat":35.00936111,"lng":135.86355556,"geo_status":"db","era":"明治5年／昭和9年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積166㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0311","desc":"通りに西面する二階建町家で、建築面積一六六平方メートル、切妻造桟瓦葺。正面は腰を御影石張とし、二階に虫籠窓を残す。内部北半は、米を搬出入するため広い通土間を通し、力感のある小屋組を見せる吹放しとする。昭和初期の軒切り改修を受けた町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009313"},{"id":"00009316","register_sub_id":"101","register_pk":"194109","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央1-209","lat":35.00944444,"lng":135.86355556,"geo_status":"db","era":"明治43年／昭和9年・平成期改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0314","desc":"通りに西面する二階建町家で、建築面積七六平方メートル、切妻造桟瓦葺である。下階正面は、北側より潜戸付きの大戸、格子、出格子で構成し、上階は両端間を漆喰塗、他はガラス窓とし、軒は出桁造とする。隣接する中野家住宅とともに町並み景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009316"},{"id":"00009315","register_sub_id":"101","register_pk":"194108","name":"中野家住宅土蔵","kana":"なかのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央1-208","lat":35.00927778,"lng":135.86377778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0313","desc":"主屋後方に中庭を介して建つ土蔵。土蔵造二階建、桁行四・八メートル梁間三・九メートル、切妻造本瓦葺で西正面の出入口に土庇を設ける。外壁は漆喰塗で腰に竪板を張る。開口部の扉に木瓜形模様を黒漆喰で表し、窓庇の持送りに繰形を施すなど技巧を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009315"},{"id":"00009314","register_sub_id":"101","register_pk":"194107","name":"中野家住宅離れ","kana":"なかのけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央1-208","lat":35.00938889,"lng":135.86366667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0312","desc":"主屋東半部の北側に並行し、西面して建つ。木造平屋建、建築面積五三平方メートル、切妻造桟瓦葺である。一二畳主室は丁寧なつくりのトコ棚を備え、西側に次の間を介して坪庭を配し、主室東側を中庭とする。町家の敷地内に構える、落着いた佇まいの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009314"},{"id":"00009625","register_sub_id":"101","register_pk":"194621","name":"成宮家住宅主屋","kana":"なるみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市鳥居本町1669","lat":35.28091112,"lng":136.28329234,"geo_status":"db","era":"明治36頃","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積157㎡","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0333","desc":"中山道鳥居本宿に西面して建つ町家。木造平屋一部二階建で上部を漆喰塗込として虫籠窓を穿つ。内部は南寄りを通土間とし、床上部は手前よりイマなどを並べる。正面の出格子を駒寄せで囲い、土間入口にトバコと呼ぶ物入を設けるなど彦根の町家の特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009625"},{"id":"00009626","register_sub_id":"101","register_pk":"194622","name":"成宮家住宅土蔵","kana":"なるみやけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市鳥居本町1669","lat":35.28088733,"lng":136.2834708,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡、塀付","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0334","desc":"主屋の東後方に東西棟で建つ。桁行六・九メートル梁間四メートル、土蔵造二階建、切妻造桟瓦葺で、西妻を戸口として下屋を設ける。外壁漆喰塗で鉢巻を廻らし、腰を竪板張とする。二階両妻面に庇付の窓を穿ち、窓枠に絵様を象るなど、丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009626"},{"id":"00000252","register_sub_id":"101","register_pk":"101242","name":"仁木家住宅洋館","kana":"にきけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲南町深川市場字里ノ内41","lat":34.93053891,"lng":136.162896,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建，瓦葺，建築面積60㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"25 － 0006","desc":"１階は、一辺約７メートルの正方形の右手が前後に突き出す平面になる。２階の妻壁をハーフティンバー、その他をドイツ壁としている点は特徴的。町屋の並ぶ町並みの中で、Ｔ字路の突き当たりに位置するひときわ目立つ２階建ての洋風建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000252"},{"id":"00000736","register_sub_id":"101","register_pk":"101726","name":"西田家住宅主屋","kana":"にしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市綣八丁目923","lat":35.03906266,"lng":135.97768933,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建，瓦葺，建築面積167㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0048","desc":"代々宮大工を生業とした旧家で，現在の主屋は３代前の久兵衛によって明治６年頃に建築されたと伝える。切妻造，桟瓦葺の母屋の左妻に厩を落棟として設け，残る３方に庇下屋を取り付ける。平面は四間取で，大棟の軒は塗込めとする標準的な造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000736"},{"id":"00000737","register_sub_id":"101","register_pk":"101727","name":"西田家住宅離れ","kana":"にしだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市綣八丁目923","lat":35.03893636,"lng":135.97763806,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建，瓦葺，建築面積74㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0049","desc":"先々代の久太郎が明治２８年頃に建てたと伝える。切妻造，桟瓦葺の平屋建になる妻入の土蔵で，正面及び右側面に１間の下屋庇が取り付く。近年正面の庇を取り込み部屋に改造したが，母屋とともに先々代の優れた技量の一端を知ることが出来る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000737"},{"id":"00003438","register_sub_id":"101","register_pk":"104428","name":"野村家住宅米蔵","kana":"のむらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市大沢町656","lat":35.13417883,"lng":136.25101486,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0228","desc":"主屋の前方，敷地南東隅の道路際に建つ。桁行３間，梁間２間，切妻造，２階建で，１階内部は前室とその奥の米貯蔵室の２室に分ける。米貯蔵室は大壁で仕切り，一段高く張った天井も土を厚く載せ温湿度の調整に工夫する。小規模だが，特徴ある形式をもつ土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003438"},{"id":"00003436","register_sub_id":"101","register_pk":"104426","name":"野村家住宅主屋","kana":"のむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市大沢町656","lat":35.13430469,"lng":136.25104104,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0226","desc":"集落ほぼ中央の宅地に南西方を向いて建つ。木造，２階建，桟瓦葺で，１階は土間の上手に整形４間取の床上部を取り，２階も田字に座敷を配す。客室は床，違棚を備えた丁寧な造作になり，立ちが高く起り屋根や２階の虫籠窓など，外観の随所に目立つ意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003436"},{"id":"00003437","register_sub_id":"101","register_pk":"104427","name":"野村家住宅土蔵","kana":"のむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市大沢町656","lat":35.1343959,"lng":136.25094528,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0227","desc":"桁行３間半，梁間２間半，２階建の土蔵で，正面に２間四方の蔵前を設けて主屋北西に接続する。花崗岩切石積の高い基壇上に建ち，置屋根の母屋・垂木を塗り込め，戸前や窓回漆喰塗に絵様を施すなど入念な造りになり，屋敷構えを構成するうえで欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003437"},{"id":"00012751","register_sub_id":"101","register_pk":"367654","name":"迫間家住宅主屋","kana":"はさまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市大橋町17他","lat":35.259785,"lng":136.25702083,"geo_status":"db","era":"江戸後期／平成25年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"25 － 0420","desc":"彦根旧城下南端にあるもと商家。主屋は街路に東面して建つ切妻造桟瓦葺のつし二階建と、その背面の蔵座敷からなる。内外に改変があるが、軒の低い正面や二階の虫籠窓は旧状を留め、小屋組等に旧材を残す。江戸後期に遡る希少な町家建築で城下の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012751"},{"id":"00012752","register_sub_id":"101","register_pk":"367655","name":"迫間家住宅土蔵","kana":"はさまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市大橋町17他","lat":35.259785,"lng":136.25702083,"geo_status":"db","era":"江戸後期／平成25年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"25 － 0421","desc":"敷地の最奥部に東面して建つ。土蔵造二階建、切妻造桟瓦葺で、外壁は漆喰塗とし、軒先は垂木形を現して塗込める。小屋組は和小屋。内外に改変があるが、屋根から軒回りにかけて旧状を留め、小屋組等に旧材を残す。彦根城下の伝統的な町家の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012752"},{"id":"00013267","register_sub_id":"101","register_pk":"366256","name":"橋和田家住宅主屋","kana":"はしわだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央一丁目115他","lat":35.00761111,"lng":135.863525,"geo_status":"db","era":"明治中期／昭和8年頃・平成22年・同29年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺、建築面積185㎡","structure_material":"木造2階一部3階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0447","desc":"旧東海道に南面し、大津を代表する呉服商が建てた、広い間口の町家。正面は昭和8年頃の道路拡幅に伴う軒切り後の姿で、建ちが高く、上下階とも出桁造とする。一階は出格子を設え、二階は柱と長押を現す。昭和初期の大津における町家改変の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013267"},{"id":"00013268","register_sub_id":"101","register_pk":"366257","name":"橋和田家住宅土蔵","kana":"はしわだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市中央一丁目115","lat":35.00771111,"lng":135.86345278,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0448","desc":"主屋北西に南北棟で建つ、土蔵造二階建、切妻造桟瓦葺。東面南寄りに開く戸口の瓦庇を主屋背面の縁と繋いで連絡する。外壁漆喰塗で軒先まで塗込め、戸口の楣に丸に花菱紋と躍動的な波涛紋の鏝絵を飾る。戸口と二階窓に掛子塗土戸を吊る、丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013268"},{"id":"00008138","register_sub_id":"101","register_pk":"132579","name":"初田家住宅主屋","kana":"はつたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央2-14","lat":35.00777491,"lng":135.86635048,"geo_status":"db","era":"江戸末期／昭和9年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0289","desc":"中町通りに南面する、間口９．１ｍの２階建町家、切妻造桟瓦葺で、東半部を落棟とし、越屋根を付ける。東寄りを土間とし、西側は食違いに五室を設ける。白漆喰塗の真壁造で、出桁造とし２階に太めの鉄格子の虫籠窓、１階に出格子を残す。大津市内の典型的な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008138"},{"id":"00008139","register_sub_id":"101","register_pk":"132580","name":"初田家住宅土蔵","kana":"はつたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央2-14","lat":35.00790453,"lng":135.86641918,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0290","desc":"主屋の北奥に、南北棟で建つ。切妻造本瓦葺、桁行６．０ｍ梁間４．８ｍの２階建土蔵。切石積基礎上に建ち、白漆喰仕上げとする。南面に庇付の出入口や窓を穿つ。庇の持送りや出入口の鳥居形など品よく仕上げる。内部は板敷で、祭礼のしつらえなどを保管する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008139"},{"id":"00008140","register_sub_id":"101","register_pk":"132581","name":"初田家住宅塀","kana":"はつたけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市中央2-14","lat":35.00786435,"lng":135.86646196,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長9.2m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0291","desc":"敷地東側の通りに面して、主屋背面から北に延び、延長９．２ｍ。切石積基壇上に方柱を建て、腕木を出し、桁を支持する。通り側に角桟塀瓦、敷地側に桟瓦を葺く。高く竪板を張り、上部は白漆喰仕上げとする。主屋と一連で、伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008140"},{"id":"00010834","register_sub_id":"101","register_pk":"201669","name":"東家住宅石垣","kana":"ひがしけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町下豊浦字敷来2700","lat":35.150729,"lng":136.134203,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、総延長58m","structure_material":"石造","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0378","desc":"主屋正面から南北にのびて敷地西辺を画す、高さ一メートル内外の野面積みの石垣。南側は表門前の虎口状の構えから南に延長三〇メートル幅一・五メートル内外、北側は主屋式台前の庭門を起点に延長二八メートル幅一メートル弱である。旧家の格式を伝える石垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010834"},{"id":"00010832","register_sub_id":"101","register_pk":"201667","name":"東家住宅主屋","kana":"ひがしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町下豊浦字敷来2700","lat":35.150813,"lng":136.134335,"geo_status":"db","era":"江戸後期／平成10改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺(鉄板仮葺)、建築面積144㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0376","desc":"旧安土城下の街道沿いの敷地に西面して建ち、入母屋造茅葺（鉄板仮葺）で下屋を廻らす。南端を土間、食違い六間取の床上部は表列上手にオクザシキを配し、土間寄りのデイに式台を構え、裏手にブツマなどを配する。湖東地域における近世大型民家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010832"},{"id":"00010833","register_sub_id":"101","register_pk":"201668","name":"東家住宅土蔵","kana":"ひがしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町下豊浦字敷来2700","lat":35.150798,"lng":136.134511,"geo_status":"db","era":"文政12","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0377","desc":"主屋の裏側に南北棟で建つ。桁行五・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺で、西正面に戸口を開き、下屋を設ける。外壁漆喰塗で腰を竪板張、二階妻壁に丸窓や庇付の小窓を穿つ。小屋は登梁形式とする。近世の屋敷構えを伝える旧文庫蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010833"},{"id":"00000975","register_sub_id":"101","register_pk":"101965","name":"日牟禮庵旧流し場","kana":"ひむれあんきゅうながしば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13551029,"lng":136.08548959,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積38㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0098","desc":"主屋の背後に接続して建つ。平屋建，桟瓦葺の建物。内部は東側に離れへと通じる廊下並びに便所・風呂場等を設け，西側を土間とする。一部改造はみられるが，この地域の江戸時代の伝統的な町家における建築物の配置構成をよく示す事例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000975"},{"id":"00000974","register_sub_id":"101","register_pk":"101964","name":"日牟禮庵座敷","kana":"ひむれあんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13554928,"lng":136.08549182,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造２階建，瓦葺，建築面積80㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0097","desc":"主屋東面後方に接続して建ち，南側に廊下・便所が附属する。屋敷地東側を通る道路に妻面を見せ，廊下東面を土塀状につくり，町並の景観に配慮したつくりになる。２階建，桟瓦葺で，主屋と比べ，２階の階高が高いことに時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000974"},{"id":"00000973","register_sub_id":"101","register_pk":"101963","name":"日牟禮庵主屋","kana":"ひむれあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13556711,"lng":136.08544726,"geo_status":"db","era":"19世紀前期","year":1820,"year_source":"estimated","year_min":1801,"year_max":1840,"year_label":"19世紀前期","structure":"木造平屋建，瓦葺，建築面積117㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0096","desc":"近江八幡の旧市街地の西端，旧京街道に面して建つ町家で，前方を改修してそば屋の店舗としている。切妻造，平入，桟瓦葺でつし２階をもち，通り土間に面して４室を並べた形になる。往時の景観をよくとどめる旧京街道沿い西方地区の町家の好例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000973"},{"id":"00000979","register_sub_id":"101","register_pk":"101969","name":"日牟禮庵高塀","kana":"ひむれあんたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13547798,"lng":136.08542498,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造，瓦葺，木製門扉附属，延長5.8m","structure_material":"木造","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0102","desc":"主屋の正面東側，旧京街道に面して建つ，真壁造で腰に板を張った土塀で，街道沿いの町並景観の構成要素のひとつ。外観の意匠は，主屋正面にあわせており，漆喰壁が連続する東方の通り側の意匠と違いをもたせている。出入口の上の庇は，近年の改造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000979"},{"id":"00000977","register_sub_id":"101","register_pk":"101967","name":"日牟禮庵西土蔵","kana":"ひむれあんにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13547798,"lng":136.08542498,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積46㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0100","desc":"離れの南方に建つ，２階建，桟瓦葺，平入の土蔵。東側に並んで建つ東土蔵とともに，屋敷地の南端に位置し，防火上の役割を果たしている。什器や道具を収納するための蔵で，屋敷地の主要な構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000977"},{"id":"00000976","register_sub_id":"101","register_pk":"101966","name":"日牟禮庵離れ","kana":"ひむれあんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13545586,"lng":136.0855511,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造２階建，瓦葺，建築面積30㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0099","desc":"旧流し場の後方東寄りに接続して建つ，隠居の間として使われた建物。切妻造，２階建，桟瓦葺で，１・２階とも１室からなる。外部は数寄屋風のつくりで，内部の意匠は座敷とよく似る。この地域の伝統的な町家における住まい方の近代化を示す好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000976"},{"id":"00000978","register_sub_id":"101","register_pk":"101968","name":"日牟禮庵東土蔵","kana":"ひむれあんひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市西元町61","lat":35.13547798,"lng":136.08542498,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積36㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0101","desc":"２階建，桟瓦葺，妻入の土蔵で，什器や道具を収納するための蔵。西土蔵と同じく屋敷構えの主要な構成要素で，屋敷地東側を通る道路からみえる平側の壁面は，座敷とその南に附属する廊下と一連の意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000978"},{"id":"00000589","register_sub_id":"101","register_pk":"101579","name":"深田家住宅主屋","kana":"ふかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市能登川町606","lat":35.17424292,"lng":136.15432598,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造２階建，瓦葺，建築面積156㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"25 － 0036","desc":"街道からの外観は一般的な町屋の造りであるが，モダンなプロポーション感覚を見せる。階下の間取りは一般的であるが，階上の各部屋はそれぞれ意匠を変えて趣向を凝らし，大広間はむくり格天井や蝙蝠型の下地窓などを随所に配し数寄屋空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000589"},{"id":"00000591","register_sub_id":"101","register_pk":"101581","name":"深田家住宅土蔵","kana":"ふかだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県東近江市能登川町606","lat":35.17420595,"lng":136.15440408,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積27㎡","structure_material":"土蔵造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"25 － 0038","desc":"主屋の西側に接して建ち，妻面を街道に向ける。蔵前を東面の平に設ける。正面4.28メートル，奥行6.30メートルの規模で一般的な土蔵形式をとる。外装は腰を竪羽目とし，上部を波形鉄板張りとしている。屋敷構えをつくるうえで欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000591"},{"id":"00000590","register_sub_id":"101","register_pk":"101580","name":"深田家住宅離れ","kana":"ふかだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市能登川町606","lat":35.17431765,"lng":136.15430737,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積29㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"25 － 0037","desc":"主屋玄関奥の土間から背面庭南方に延び，風呂場や便所などを一列にならべる。外観は竪羽目の付属屋的な造りとしているが，廊下の天井を化粧屋根裏とするなど「離れ」に相応しい内部意匠をとる。屋敷全体の構成にとって欠くことのできない施設になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000590"},{"id":"00001279","register_sub_id":"101","register_pk":"102269","name":"福井三四郎家住宅土蔵","kana":"ふくいさんしろうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県高島市勝野1320","lat":35.29645107,"lng":136.01197396,"geo_status":"db","era":"19世紀前期","year":1820,"year_source":"estimated","year_min":1801,"year_max":1840,"year_label":"19世紀前期","structure":"土蔵造２階建，瓦葺，建築面積39㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"25 － 0116","desc":"敷地の北西端、主屋の背面に建つ土蔵。福井家が営んでいた醤油醸造のためではなく、生活用品を収めていた。桁行三間、梁間二間の規模を持ち、壁の上部と軒周りを漆喰塗りとするほかは縦板貼りである。かつての城下町の商家の様子を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001279"},{"id":"00002049","register_sub_id":"101","register_pk":"103039","name":"藤居本家住宅主屋","kana":"ふじいほんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野792","lat":35.18405589,"lng":136.20747942,"geo_status":"db","era":"大正5頃／昭和30代移築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積328㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0141","desc":"もと日野町の中村源左衛門家住宅主屋を現在地に移築したもの。北東面を正面とした桁行２７ｍの２階建で，２列３室六間取りの座敷部を入母屋造とし，土間部は棟を落とした切妻造とする。全体にたちが高く，土間の端整な架構などに近代的傾向が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002049"},{"id":"00002050","register_sub_id":"101","register_pk":"103040","name":"藤居本家住宅書院","kana":"ふじいほんけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野792","lat":35.18430934,"lng":136.20745821,"geo_status":"db","era":"大正5頃／昭和30代移築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0142","desc":"主屋の座敷側に繋がっていたが，敷地の関係で主屋とは切り離されて棟を直交するかたちに移築。入母屋造の玄関棟，１２畳半・１０畳２室を主室とする入母屋造の座敷棟及び風呂便所棟から成る。主屋とともに大正期日野商人の住宅観と財力を示す事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002050"},{"id":"00009184","register_sub_id":"101","register_pk":"164737","name":"ふじ石亭客間棟","kana":"ふじせきていきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市朝日町47他","lat":35.37773674,"lng":136.27006174,"geo_status":"db","era":"明治17年頃／平成17年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"土蔵南面の玄関と茶室、東面の広間からなるＬ字形平面をなし、建築面積115平方メートル、木造平屋建、入母屋造及び切妻造、桟瓦葺である。玄関は6畳間をもつ式台玄関で、24畳の広間は庭に面して縁を廻らす。気品ある雰囲気を有する接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009184"},{"id":"00009183","register_sub_id":"101","register_pk":"164736","name":"ふじ石亭蔵","kana":"ふじせきていくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市朝日町47他","lat":35.37774673,"lng":136.26997418,"geo_status":"db","era":"明治17年頃／平成17年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造、瓦葺、建築面積23㎡","structure_material":"土蔵造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の東側に東西棟で建ち、桁行5.6メートル梁間4.0メートル、土蔵造、切妻造桟瓦葺である。北面の主屋から続く通り土間側を出入口として、掛子塗の扉を吊り、外壁は漆喰塗仕上げとする。素封家の屋敷構えを伝える内蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009183"},{"id":"00009182","register_sub_id":"101","register_pk":"164735","name":"ふじ石亭主屋","kana":"ふじせきていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市朝日町47他","lat":35.37771199,"lng":136.2698357,"geo_status":"db","era":"明治17年頃／平成17年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積123㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"市街地の通りに面して建つ。桁行16.8メートル梁間7.5メートル、木造平屋1部2階建、入母屋造及び切妻造、妻入、桟瓦葺で、正面に下屋を付す。外壁上部は軒裏や妻壁まで漆喰で塗籠め、柱形を表し、正面に穿たれた窓に鉄格子をはめ、重厚な構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009182"},{"id":"00013269","register_sub_id":"101","register_pk":"366258","name":"藤原家住宅","kana":"ふじはらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央一丁目115-5","lat":35.00794444,"lng":135.863675,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0449","desc":"通りから折曲りに延びる小路の最奥に南面して建つ。もと二戸一棟の長屋形式で、現在は内部を一体化している。正面外観は往時を残し、両戸の東寄りに玄関を構え、西側に格子を建てる。上下階とも真壁造で、軒は出桁造とする。戦前の大津の長屋形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013269"},{"id":"00006572","register_sub_id":"101","register_pk":"107555","name":"古川家住宅客間棟","kana":"ふるかわけじゅうたくきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院919","lat":35.20742,"lng":136.234314,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0243","desc":"主屋の北西角に縁を介して接続する東西棟の入母屋造，平屋建である。４畳半大の２室からなり，西室には釣床を設けて濡縁を廻らす。屋根は勾配の緩い桟瓦葺で軒廻りは銅板葺とする。良材を用いた丁寧な造作で，小規模ながら瀟洒な数寄屋風の接客空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006572"},{"id":"00006574","register_sub_id":"101","register_pk":"107557","name":"古川家住宅蔵","kana":"ふるかわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院919","lat":35.207554,"lng":136.23407,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0245","desc":"敷地の中央西寄りに建つ土蔵造２階建。桁行３間半，梁間２間半規模の南北棟で，切妻造，桟瓦葺の置屋根とする。東側の渡廊下に戸口を開く。切石積の基礎上に建ち，外壁は白漆喰塗で，腰を縦板張とする。１階西面と２階南面に窓を開き外観のアクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006574"},{"id":"00006573","register_sub_id":"101","register_pk":"107556","name":"古川家住宅離れ","kana":"ふるかわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院919","lat":35.207504,"lng":136.23419908,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積65㎡、渡廊下付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0244","desc":"敷地の北西に建つ木造平屋建。客間棟の西側縁から長さ７間半の渡廊下で接続する。１畳大の釣床を設けた８畳座敷と４畳半の次の間を雁行して配し，庭側の濡縁が蔵の東に達する。屋根は入母屋造，桟瓦葺で縁庇は銅板葺。庭からの景観を意識した構成である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006573"},{"id":"00011331","register_sub_id":"101","register_pk":"209168","name":"不破家住宅主屋","kana":"ふわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町字上出2351","lat":35.234156,"lng":136.256669,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造2階建、瓦葺、建築面積223㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0380","desc":"旧高宮宿で通りに西面する入母屋造妻入の二階建。平面は右手に幅広の土間を通し、左手に四室ずつ二列並べる。良材を用いた普請で座敷飾も上質である。塗込の外部に柱形などを表し、正面開口部に出格子を設ける。重厚な構えの大型住宅で、当宿の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011331"},{"id":"00011334","register_sub_id":"101","register_pk":"209171","name":"不破家住宅高塀","kana":"ふわけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市高宮町字上出2351","lat":35.23410812,"lng":136.25689706,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長20m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"25－0383","desc":"主屋北東隅から矩折れにのびて土蔵に至り、主屋裏庭を画す塀。敷地北辺分は水路の石垣上に高さ三・一メートルの塀を建て、東辺分は棟を落とし、いずれも腕木で軒を受け切妻造桟瓦葺とする。腰高に竪板を張り、上部漆喰塗とする。旧高宮宿の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011334"}];
